import { useCallback, useEffect, useMemo, useState } from "react";
import { ChevronDown, ChevronRight, Plus, ExternalLink, LayoutList } from "lucide-react";
import { toast } from "sonner";
import { useDbStore } from "@/stores/database-context";
import { applyFilters, isCellEmpty, sortRows } from "@/lib/database-query";
import { NO_GROUP, cellValueForGroup, defaultBoardField, groupRowsForBoard } from "@/lib/board-calendar";
import { formatCellValue, parseFieldOptions } from "@/lib/database-values";
import { relationCellText, relationTarget, type RelationDb } from "@/lib/relation";
import { useRelationDbs } from "./use-database-data";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { SelectChips } from "./editors";
import { ROW_FOCUS_CLASS, useRowFocus } from "./rowFocus";
import { RowDetailPanel } from "./RowDetail";
import { cn } from "@/lib/utils";
import { t } from "@/lib/i18n";
import { logger } from "@/lib/logger";
import { patchViewConfig, readViewConfig } from "@/lib/view-config";
import type { CellValue, DatabaseField } from "@/types/database";
import type { View } from "@/types/models";

/** Board 看板视图（说明书 11 节 M5）：按单选字段分组 + 卡片拖拽改值 */
export function BoardView({
  view,
  source,
  tabs,
  onGoGrid,
}: {
  /** 当前视图：分组字段等显示配置的归属 */
  view: View;
  /** 宿主页面：标题、重命名与行详情的父子归属 */
  source: View;
  /** 顶栏左侧的视图标签栏（页内切换 grid/board/calendar） */
  tabs?: React.ReactNode;
  /** 无单选字段时引导回到表格视图 */
  onGoGrid?: () => void;
}) {
  const store = useDbStore();
  const { fields, rows, cells, loading, sorts, filters, filterMode, rowDetail } = store;
  const { openRowDetail, closeRowDetail } = store;

  const [groupFieldId, setGroupFieldId] = useState<string | null>(() => readViewConfig(view).boardFieldId ?? null);
  // null = 未配置（沿用"主字段之后前 3 个可见字段"的默认启发式）；数组 = 用户显式勾选的字段
  const [cardFieldIds, setCardFieldIds] = useState<string[] | null>(() => readViewConfig(view).cardFieldIds ?? null);
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  const [draggingRow, setDraggingRow] = useState<string | null>(null);
  const [dragOverGroup, setDragOverGroup] = useState<string | null>(null);
  const [newGroupName, setNewGroupName] = useState("");
  const [newGroupOpen, setNewGroupOpen] = useState(false);

  useEffect(() => {
    store.load(view).catch((e: unknown) => logger.error("board.load", e));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.id]);

  const changeGroupField = (id: string | null) => {
    setGroupFieldId(id);
    patchViewConfig(view, { boardFieldId: id ?? "" });
  };

  // 初始化默认分组字段
  useEffect(() => {
    if (fields.length === 0) return;
    const def = defaultBoardField(fields);
    if (groupFieldId && fields.some((f) => f.id === groupFieldId && f.field_type === "single_select")) {
      return;
    }
    setGroupFieldId(def?.id ?? null);
  }, [fields, groupFieldId]);

  const visibleFields = useMemo(() => fields.filter((f) => f.is_hidden === 0), [fields]);
  const primaryField = visibleFields[0] ?? null;
  const groupField = fields.find((f) => f.id === groupFieldId) ?? null;
  const selectFields = useMemo(() => fields.filter((f) => f.field_type === "single_select"), [fields]);

  const cardCandidates = useMemo(() => visibleFields.slice(1), [visibleFields]);
  const defaultCardFieldIds = useMemo(() => cardCandidates.slice(0, 3).map((f) => f.id), [cardCandidates]);
  const cardSubFields = useMemo(() => {
    const ids = cardFieldIds ?? defaultCardFieldIds;
    return ids.map((id) => cardCandidates.find((f) => f.id === id)).filter((f): f is DatabaseField => !!f);
  }, [cardCandidates, cardFieldIds, defaultCardFieldIds]);

  // 关联列（主字段/卡片副信息）要解析目标行标题：把本表所有关联字段的目标视图拉进缓存
  const relationDbOf = useRelationDbs(fields);

  const toggleCardField = (id: string) => {
    const current = cardFieldIds ?? defaultCardFieldIds;
    const next = current.includes(id) ? current.filter((x) => x !== id) : [...current, id];
    setCardFieldIds(next);
    patchViewConfig(view, { cardFieldIds: next });
  };

  const displayRows = useMemo(() => {
    const filtered = applyFilters(rows, cells, filters, fields, filterMode);
    return sortRows(filtered, cells, sorts);
  }, [rows, cells, filters, fields, filterMode, sorts]);

  const groups = useMemo(() => {
    if (!groupField) return [];
    return groupRowsForBoard(displayRows, cells, groupField);
  }, [groupField, displayRows, cells]);

  // 搜索命中定位：折叠键作 revision，命中卡片所在列一展开就能重新定位
  const collapsedKey = [...collapsedGroups].join("|");
  const { scrollerRef, focusRowId } = useRowFocus(collapsedKey);
  useEffect(() => {
    if (!focusRowId) return;
    const hit = groups.find((g) => g.rows.some((r) => r.id === focusRowId));
    if (!hit || !collapsedGroups.has(hit.key)) return;
    setCollapsedGroups((prev) => {
      const next = new Set(prev);
      next.delete(hit.key);
      return next;
    });
  }, [focusRowId, groups, collapsedGroups]);

  const commitCell = useCallback(
    async (rowId: string, fieldId: string, value: CellValue) => {
      try {
        await store.setCell(rowId, fieldId, value);
      } catch (e) {
        toast.error(t("error.db", { message: String(e) }));
      }
    },
    [store],
  );

  const addCardInGroup = async (groupKey: string) => {
    if (!groupField) return;
    try {
      const row = await store.addRow();
      if (row && groupKey !== NO_GROUP) {
        await store.setCell(row.id, groupField.id, cellValueForGroup(groupKey));
      }
    } catch (e) {
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const addGroup = async () => {
    const name = newGroupName.trim();
    if (!name || !groupField) return;
    try {
      await store.addSelectOption(groupField.id, name);
      setNewGroupName("");
      setNewGroupOpen(false);
    } catch (e) {
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const toggleAllCollapsed = (collapse: boolean) => {
    if (collapse) setCollapsedGroups(new Set(groups.map((g) => g.key)));
    else setCollapsedGroups(new Set());
  };

  if (loading && fields.length === 0) {
    return <div className="flex h-full items-center justify-center text-sm text-neutral-500">{t("app.loading")}</div>;
  }

  return (
    <div className="relative flex h-full flex-col overflow-hidden bg-white">
      {/* 顶栏（44px，和 GridView 一致）：左侧为页内视图切换 */}
      <div className="flex h-11 shrink-0 items-center gap-2 border-b border-neutral-200 px-6">
        <div className="flex min-w-0 flex-1 items-center">{tabs}</div>

        <div className="flex shrink-0 items-center gap-1">
          {/* 分组字段切换 */}
          <div className="flex items-center gap-1.5 rounded-md border border-neutral-300 bg-white px-2 py-1 text-xs text-neutral-700">
            <span className="text-neutral-500">{t("board.groupBy")}:</span>
            <select
              className="bg-transparent text-xs outline-none"
              value={groupFieldId ?? ""}
              onChange={(e) => changeGroupField(e.target.value || null)}
            >
              {selectFields.length === 0 && <option value="">{t("board.noField")}</option>}
              {selectFields.map((f) => (
                <option key={f.id} value={f.id}>
                  {f.name}
                </option>
              ))}
            </select>
          </div>

          {/* 卡片字段配置 */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm">
                <LayoutList className="h-3.5 w-3.5" />
                {t("board.cardFields")}
                <ChevronDown className="h-3 w-3" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
              <DropdownMenuLabel>{t("board.cardFieldsHint")}</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {cardCandidates.map((f) => (
                <DropdownMenuCheckboxItem
                  key={f.id}
                  checked={(cardFieldIds ?? defaultCardFieldIds).includes(f.id)}
                  onSelect={(e) => e.preventDefault()}
                  onCheckedChange={() => toggleCardField(f.id)}
                >
                  {f.name}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          <Button variant="ghost" size="sm" onClick={() => toggleAllCollapsed(true)}>
            {t("board.collapseAll")}
          </Button>
          <Button variant="ghost" size="sm" onClick={() => toggleAllCollapsed(false)}>
            {t("board.expandAll")}
          </Button>
        </div>
      </div>

      {/* 空态：没有单选字段 */}
      {!groupField ? (
        <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 px-6 text-center">
          <div className="text-4xl">🗂️</div>
          <h2 className="text-base font-semibold text-neutral-800">{t("board.noField")}</h2>
          <p className="max-w-md text-sm text-neutral-500">{t("board.noFieldDesc")}</p>
          {onGoGrid && (
            <Button size="sm" onClick={onGoGrid}>
              {t("board.goGrid")}
            </Button>
          )}
        </div>
      ) : (
        <div ref={scrollerRef} className="min-h-0 flex-1 overflow-x-auto overflow-y-hidden">
          <div className="flex h-full min-w-full gap-3 p-4">
            {groups.map((group) => {
              const collapsed = collapsedGroups.has(group.key);
              const isUngrouped = group.key === NO_GROUP;
              const optionColor = group.option?.color ?? null;
              const accent = optionColor ? optionColorToClass(optionColor) : null;
              const overThis = dragOverGroup === group.key;
              return (
                <div
                  key={group.key}
                  className={cn(
                    "flex w-72 shrink-0 flex-col overflow-hidden rounded-lg border bg-neutral-100/50",
                    overThis && draggingRow
                      ? "border-brand-500 bg-brand-50 ring-1 ring-brand-500"
                      : "border-neutral-200",
                  )}
                  onDragOver={(e) => {
                    if (draggingRow) {
                      e.preventDefault();
                      if (dragOverGroup !== group.key) setDragOverGroup(group.key);
                    }
                  }}
                  onDragLeave={() => {
                    if (dragOverGroup === group.key) setDragOverGroup(null);
                  }}
                  onDrop={(e) => {
                    e.preventDefault();
                    if (draggingRow) {
                      const rowId = draggingRow;
                      setDraggingRow(null);
                      setDragOverGroup(null);
                      void commitCell(rowId, groupField.id, cellValueForGroup(group.key));
                    }
                  }}
                >
                  {/* 列头：颜色点 + 名称 + count + 折叠 + 新增按钮 */}
                  <div className="flex items-center gap-2 border-b border-neutral-200 px-2 py-2">
                    <button
                      className="rounded p-0.5 text-neutral-500 hover:bg-neutral-200/60"
                      onClick={() => {
                        const next = new Set(collapsedGroups);
                        if (collapsed) next.delete(group.key);
                        else next.add(group.key);
                        setCollapsedGroups(next);
                      }}
                    >
                      {collapsed ? <ChevronRight className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
                    </button>
                    {accent ? (
                      <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ backgroundColor: accent }} />
                    ) : isUngrouped ? (
                      <span className="flex h-4 w-4 shrink-0 items-center justify-center text-[10px] text-neutral-400">
                        ⊘
                      </span>
                    ) : null}
                    <div className="min-w-0 flex-1 text-xs font-medium text-neutral-800">
                      {isUngrouped ? t("board.ungrouped") : (group.option?.name ?? group.key)}
                      <span className="ml-1.5 text-[10px] font-normal text-neutral-400">{group.rows.length}</span>
                    </div>
                    <button
                      className="rounded p-0.5 text-neutral-500 hover:bg-neutral-200/60"
                      onClick={() => addCardInGroup(group.key)}
                      title={t("board.addCard")}
                    >
                      <Plus className="h-3.5 w-3.5" />
                    </button>
                  </div>

                  {/* 卡片列表（或折叠占位） */}
                  {collapsed ? (
                    <div className="px-2 py-2 text-[11px] text-neutral-400">
                      {t("board.collapseAll")}: {group.rows.length}
                    </div>
                  ) : (
                    <div className="flex flex-1 flex-col gap-3 overflow-y-auto px-2 py-2">
                      {group.rows.map((row) => (
                        <BoardCard
                          key={row.id}
                          row={row}
                          primaryField={primaryField}
                          subFields={cardSubFields}
                          subFieldsExplicit={cardFieldIds !== null}
                          cells={cells}
                          relationDbOf={relationDbOf}
                          dragging={draggingRow === row.id}
                          focused={focusRowId === row.id}
                          onDragStart={() => setDraggingRow(row.id)}
                          onDragEnd={() => {
                            if (draggingRow === row.id) setDraggingRow(null);
                            if (dragOverGroup === group.key) setDragOverGroup(null);
                          }}
                          onOpenDetail={() => void openRowDetail(row, source)}
                        />
                      ))}
                      {/* 新建行按钮 */}
                      <button
                        className="flex items-center gap-1 rounded-md px-2 py-1.5 text-left text-[12px] text-neutral-500 hover:bg-white hover:text-neutral-700"
                        onClick={() => addCardInGroup(group.key)}
                      >
                        <Plus className="h-3.5 w-3.5" />
                        {t("board.addCard")}
                      </button>
                    </div>
                  )}
                </div>
              );
            })}

            {/* 新建分组：放在最右侧，可输入 name 创建选项 */}
            <div className="flex w-72 shrink-0 flex-col rounded-lg border border-dashed border-neutral-300 bg-neutral-50/60 p-3">
              {newGroupOpen ? (
                <div className="flex gap-1">
                  <input
                    autoFocus
                    className="flex-1 rounded border border-neutral-300 bg-white px-2 py-1 text-xs outline-none focus:border-brand-500"
                    placeholder={t("board.addGroupPlaceholder")}
                    value={newGroupName}
                    onChange={(e) => setNewGroupName(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") void addGroup();
                      if (e.key === "Escape") {
                        setNewGroupOpen(false);
                        setNewGroupName("");
                      }
                    }}
                  />
                  <Button size="sm" onClick={() => void addGroup()}>
                    {t("common.add")}
                  </Button>
                </div>
              ) : (
                <button
                  className="flex items-center gap-1 text-xs text-neutral-500 hover:text-neutral-700"
                  onClick={() => setNewGroupOpen(true)}
                >
                  <Plus className="h-3.5 w-3.5" />
                  {t("board.addGroup")}
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {rowDetail && <RowDetailPanel row={rowDetail.row} view={rowDetail.view} onClose={closeRowDetail} />}
    </div>
  );
}

function BoardCard(props: {
  row: { id: string; position: number };
  primaryField: DatabaseField | null;
  /** 副信息字段：来自视图配置，未配置时由调用方给默认前三列 */
  subFields: DatabaseField[];
  /** subFields 是否为用户显式勾选：决定时间戳字段是否显示 */
  subFieldsExplicit: boolean;
  cells: Record<string, Record<string, CellValue>>;
  /** 关联列解析目标行标题（视图级缓存，见 BoardView 顶部的 ensure） */
  relationDbOf: (viewId: string) => RelationDb | undefined;
  dragging: boolean;
  /** 搜索命中的卡片：滚动定位后短时高亮 */
  focused: boolean;
  onDragStart: () => void;
  onDragEnd: () => void;
  onOpenDetail: () => void;
}) {
  const { row, primaryField, subFields, subFieldsExplicit, cells, relationDbOf, dragging, focused } = props;
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- cells 为按行稀疏映射，无单元格的行没有条目（运行时可能 undefined）
  const value = primaryField ? (cells[row.id]?.[primaryField.id] ?? null) : null;
  const title = primaryField
    ? primaryField.field_type === "relation"
      ? relationCellText(value, relationDbOf(relationTarget(primaryField) ?? ""))
      : formatCellValue(primaryField.field_type, value, parseFieldOptions(primaryField.options))
    : t("row.detailName", { n: row.position + 1 });

  // 副信息：单/多选 chips + 日期 + 复选框✓ + 文本/数字，空值不占位
  const subs: { field: DatabaseField; value: CellValue }[] = subFields
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- cells 为按行稀疏映射，无单元格的行没有条目（运行时可能 undefined）
    .map((f) => ({ field: f, value: cells[row.id]?.[f.id] ?? null }))
    .filter((s) => cardSubShown(s.field, s.value, subFieldsExplicit));

  return (
    <div
      data-row-id={row.id}
      draggable
      onDragStart={props.onDragStart}
      onDragEnd={props.onDragEnd}
      className={cn(
        "group/card cursor-grab rounded-md border bg-white p-2 shadow-sm transition active:cursor-grabbing dark:bg-neutral-800",
        dragging
          ? "opacity-40 ring-1 ring-brand-500"
          : "border-neutral-200 dark:border-neutral-700 hover:border-neutral-300 hover:shadow",
        focused && ROW_FOCUS_CLASS,
      )}
    >
      <div className="flex items-start justify-between gap-1">
        <div className="min-h-[1.25rem] min-w-0 flex-1 break-words text-[13px] font-medium leading-snug text-neutral-800 dark:text-neutral-100">
          {title || <span className="text-neutral-300 dark:text-neutral-600">{t("board.cardNamePlaceholder")}</span>}
        </div>
        <button
          type="button"
          className="shrink-0 rounded p-0.5 text-neutral-400 opacity-0 transition group-hover/card:opacity-100 hover:bg-neutral-200 hover:text-brand-600"
          title={t("row.openDetail")}
          onMouseDown={(e) => e.preventDefault()}
          onClick={(e) => {
            e.stopPropagation();
            props.onOpenDetail();
          }}
        >
          <ExternalLink className="h-3 w-3" />
        </button>
      </div>
      {subs.length > 0 && (
        <div className="mt-1.5 flex flex-wrap items-center gap-1">
          {subs.map((s) => (
            <CardSub key={s.field.id} field={s.field} value={s.value} relationDbOf={relationDbOf} />
          ))}
        </div>
      )}
    </div>
  );
}

/** 单元格是否值得占用卡片副信息位：空值不显示，未勾选的复选框不显示 */
function cardSubShown(field: DatabaseField, value: CellValue, explicit: boolean): boolean {
  if (field.field_type === "checkbox") return value === true;
  if (!explicit && (field.field_type === "created_at" || field.field_type === "last_edited_at")) return false;
  return !isCellEmpty(value);
}

function CardSub({
  field,
  value,
  relationDbOf,
}: {
  field: DatabaseField;
  value: CellValue;
  relationDbOf: (viewId: string) => RelationDb | undefined;
}) {
  if (field.field_type === "single_select" || field.field_type === "multi_select") {
    return (
      <div className="max-w-full min-h-[1rem]">
        <SelectChips field={field} value={value} compact />
      </div>
    );
  }
  if (field.field_type === "checkbox") {
    return <span className="text-[11px] font-medium text-brand-600">✓</span>;
  }
  if (field.field_type === "date") {
    const text = formatCellValue("date", value, parseFieldOptions(field.options));
    return text ? (
      <span className="rounded bg-neutral-100 px-1.5 py-0.5 text-[11px] text-neutral-600">{text}</span>
    ) : null;
  }
  // 关联列解析成目标行标题（其余类型走通用格式化）
  const text =
    field.field_type === "relation"
      ? relationCellText(value, relationDbOf(relationTarget(field) ?? ""))
      : formatCellValue(field.field_type, value, parseFieldOptions(field.options));
  if (!text) return null;
  return (
    <span
      className="max-w-[120px] truncate rounded bg-neutral-100 px-1.5 py-0.5 text-[11px] text-neutral-600"
      title={text}
    >
      {text}
    </span>
  );
}

function optionColorToClass(color: string): string | null {
  // 9 种标准色（和 NewFieldDialog 一致），这里直接把 hex/命名色作为 inline style 背景
  if (/^[0-9a-fA-F]{6}$/.test(color)) return "#" + color;
  if (/^#[0-9a-fA-F]{3,8}$/.test(color)) return color;
  switch (color) {
    case "blue":
      return "#3b82f6";
    case "green":
      return "#22c55e";
    case "orange":
      return "#f97316";
    case "red":
      return "#ef4444";
    case "purple":
      return "#a855f7";
    case "yellow":
      return "#eab308";
    case "pink":
      return "#ec4899";
    case "gray":
      return "#6b7280";
    case "cyan":
      return "#06b6d4";
  }
  return null;
}

import { useEffect, useMemo, useState } from "react";
import { ChevronLeft, ChevronRight, Plus, ExternalLink } from "lucide-react";
import { toast } from "sonner";
import { useDbStore } from "@/stores/database-context";
import { applyFilters, sortRows } from "@/lib/database-query";
import { buildCalendarMonth, cellValueForDate, defaultCalendarField, rowDateKey } from "@/lib/board-calendar";
import { formatCellValue, parseFieldOptions } from "@/lib/database-values";
import { Button } from "@/components/ui/button";
import { SelectChips } from "./editors";
import { ROW_FOCUS_CLASS, useRowFocus } from "./rowFocus";
import { RowDetailPanel } from "./RowDetail";
import { cn } from "@/lib/utils";
import { t } from "@/lib/i18n";
import { logger } from "@/lib/logger";
import { patchViewConfig, readViewConfig } from "@/lib/view-config";
import type { CellValue, DatabaseField } from "@/types/database";
import type { View } from "@/types/models";

/** Calendar 日历视图（说明书 11 节 M5）：月视图（周一起）+ 卡片拖拽改日期 */
export function CalendarView({
  view,
  source,
  tabs,
  onGoGrid,
}: {
  /** 当前视图：日期字段等显示配置的归属 */
  view: View;
  /** 宿主页面：标题、重命名与行详情的父子归属 */
  source: View;
  /** 顶栏左侧的视图标签栏（页内切换 grid/board/calendar） */
  tabs?: React.ReactNode;
  /** 无日期字段时引导回到表格视图 */
  onGoGrid?: () => void;
}) {
  const store = useDbStore();
  const { fields, rows, cells, loading, sorts, filters, filterMode, rowDetail } = store;
  const { openRowDetail, closeRowDetail } = store;

  const [dateFieldId, setDateFieldId] = useState<string | null>(() => readViewConfig(view).calendarFieldId ?? null);
  const [year, setYear] = useState<number>(new Date().getFullYear());
  const [month, setMonth] = useState<number>(new Date().getMonth() + 1);
  const [draggingRow, setDraggingRow] = useState<string | null>(null);
  const [dragOverDate, setDragOverDate] = useState<string | null>(null);

  useEffect(() => {
    store.load(view).catch((e: unknown) => logger.error("calendar.load", e));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.id]);

  const changeDateField = (id: string | null) => {
    setDateFieldId(id);
    patchViewConfig(view, { calendarFieldId: id ?? "" });
  };

  // 初始化日期字段：第一个 date/created_at/last_edited_at
  useEffect(() => {
    if (fields.length === 0) return;
    const def = defaultCalendarField(fields);
    if (
      dateFieldId &&
      fields.some((f) => f.id === dateFieldId && ["date", "created_at", "last_edited_at"].includes(f.field_type))
    ) {
      return;
    }
    setDateFieldId(def?.id ?? null);
  }, [fields, dateFieldId]);

  const visibleFields = useMemo(() => fields.filter((f) => f.is_hidden === 0), [fields]);
  const dateField = fields.find((f) => f.id === dateFieldId) ?? null;
  const dateFields = useMemo(
    () => fields.filter((f) => ["date", "created_at", "last_edited_at"].includes(f.field_type)),
    [fields],
  );

  const displayRows = useMemo(() => {
    const filtered = applyFilters(rows, cells, filters, fields, filterMode);
    return sortRows(filtered, cells, sorts);
  }, [rows, cells, filters, fields, filterMode, sorts]);

  const today = useMemo(() => {
    const d = new Date();
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }, []);

  const cal = useMemo(() => {
    if (!dateField) return null;
    return buildCalendarMonth(year, month, displayRows, cells, dateField.id);
  }, [dateField, year, month, displayRows, cells]);

  // 搜索命中定位：命中行的日期不在当前月份时先翻过去，翻完再由 useRowFocus 滚动
  const { scrollerRef, focusRowId } = useRowFocus(`${year}-${month}`);
  useEffect(() => {
    if (!focusRowId || !dateField) return;
    const row = rows.find((r) => r.id === focusRowId);
    if (!row) return;
    const key = rowDateKey(row, cells, dateField.id);
    if (!key) return;
    const hitYear = Number(key.slice(0, 4));
    const hitMonth = Number(key.slice(5, 7));
    if (hitYear === year && hitMonth === month) return;
    setYear(hitYear);
    setMonth(hitMonth);
  }, [focusRowId, rows, cells, dateField, year, month]);

  const addRowAtDate = async (dateKey: string) => {
    if (!dateField) return;
    if (dateField.field_type === "created_at" || dateField.field_type === "last_edited_at") {
      toast.error(t("error.db", { message: `Cannot set ${dateField.name}` }));
      return;
    }
    try {
      const row = await store.addRow();
      if (row) await store.setCell(row.id, dateField.id, cellValueForDate(dateKey));
    } catch (e) {
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const setRowDate = async (rowId: string, dateKey: string) => {
    if (!dateField) return;
    if (dateField.field_type === "created_at" || dateField.field_type === "last_edited_at") return;
    try {
      await store.setCell(rowId, dateField.id, cellValueForDate(dateKey));
    } catch (e) {
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const gotoPrevMonth = () => {
    setMonth((m) => {
      if (m === 1) {
        setYear((y) => y - 1);
        return 12;
      }
      return m - 1;
    });
  };
  const gotoNextMonth = () => {
    setMonth((m) => {
      if (m === 12) {
        setYear((y) => y + 1);
        return 1;
      }
      return m + 1;
    });
  };
  const gotoToday = () => {
    const d = new Date();
    setYear(d.getFullYear());
    setMonth(d.getMonth() + 1);
  };

  if (loading && fields.length === 0) {
    return <div className="flex h-full items-center justify-center text-sm text-neutral-500">{t("app.loading")}</div>;
  }

  return (
    <div className="relative flex h-full flex-col overflow-hidden bg-white">
      {/* 顶栏（44px，和 GridView 一致）：左侧为页内视图切换 */}
      <div className="flex h-11 shrink-0 items-center gap-2 border-b border-neutral-200 px-6">
        <div className="flex min-w-0 flex-1 items-center">{tabs}</div>

        <div className="flex shrink-0 items-center gap-1">
          <div className="flex items-center gap-1.5 rounded-md border border-neutral-300 bg-white px-2 py-1 text-xs text-neutral-700">
            <span className="text-neutral-500">{t("calendar.dateBy")}:</span>
            <select
              className="bg-transparent text-xs outline-none"
              value={dateFieldId ?? ""}
              onChange={(e) => changeDateField(e.target.value || null)}
            >
              {dateFields.length === 0 && <option value="">{t("calendar.noField")}</option>}
              {dateFields.map((f) => (
                <option key={f.id} value={f.id}>
                  {f.name}
                </option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-0.5 rounded-md border border-neutral-300 bg-white text-xs">
            <button className="rounded-l-md px-2 py-1 text-neutral-600 hover:bg-neutral-100" onClick={gotoPrevMonth}>
              <ChevronLeft className="h-3.5 w-3.5" />
            </button>
            <span className="px-2 font-medium text-neutral-800">
              {year} / {String(month).padStart(2, "0")}
            </span>
            <button className="px-2 py-1 text-neutral-600 hover:bg-neutral-100" onClick={gotoNextMonth}>
              <ChevronRight className="h-3.5 w-3.5" />
            </button>
          </div>

          <Button variant="ghost" size="sm" onClick={gotoToday}>
            {t("calendar.today")}
          </Button>
        </div>
      </div>

      {!dateField ? (
        <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 px-6 text-center">
          <div className="text-4xl">📅</div>
          <h2 className="text-base font-semibold text-neutral-800">{t("calendar.noField")}</h2>
          <p className="max-w-md text-sm text-neutral-500">{t("calendar.noFieldDesc")}</p>
          {onGoGrid && (
            <Button size="sm" onClick={onGoGrid}>
              {t("board.goGrid")}
            </Button>
          )}
        </div>
      ) : (
        <div ref={scrollerRef} className="min-h-0 flex-1 overflow-auto">
          <div className="flex h-full min-h-full flex-col">
            {/* 周标题行 */}
            <div className="grid grid-cols-7 border-b border-neutral-200 bg-neutral-100/60 text-[11px] text-neutral-500 dark:border-neutral-700 dark:bg-neutral-800/40 dark:text-neutral-400">
              <div className="border-r border-neutral-200 px-2 py-1 text-right dark:border-neutral-700">
                {t("calendar.wMon")}
              </div>
              <div className="border-r border-neutral-200 px-2 py-1 text-right dark:border-neutral-700">
                {t("calendar.wTue")}
              </div>
              <div className="border-r border-neutral-200 px-2 py-1 text-right dark:border-neutral-700">
                {t("calendar.wWed")}
              </div>
              <div className="border-r border-neutral-200 px-2 py-1 text-right dark:border-neutral-700">
                {t("calendar.wThu")}
              </div>
              <div className="border-r border-neutral-200 px-2 py-1 text-right dark:border-neutral-700">
                {t("calendar.wFri")}
              </div>
              <div className="border-r border-neutral-200 px-2 py-1 text-right dark:border-neutral-700">
                {t("calendar.wSat")}
              </div>
              <div className="px-2 py-1 text-right">{t("calendar.wSun")}</div>
            </div>

            {/* 日期格：6 行 × 7 列 */}
            <div className="grid flex-1 grid-cols-7 grid-rows-6 auto-rows-fr">
              {cal?.days.map((d, i) => {
                const isWeekend = i % 7 >= 5;
                const isToday = d.date === today;
                const overThis = draggingRow && dragOverDate === d.date;
                const date = d.date;
                return (
                  <div
                    key={i}
                    className={cn(
                      "group/row relative flex min-h-[120px] flex-col border-b border-r border-neutral-200 bg-white transition dark:border-neutral-700 dark:bg-neutral-900",
                      isWeekend && "bg-neutral-50/60 dark:bg-neutral-800/30",
                      d.day === null && "bg-neutral-50/30 dark:bg-neutral-900",
                      isToday && "ring-1 ring-inset ring-brand-500",
                      overThis && "bg-brand-50 ring-1 ring-inset ring-brand-500 dark:bg-brand-600/10",
                    )}
                    onDragOver={(e) => {
                      if (draggingRow && d.date) {
                        e.preventDefault();
                        if (dragOverDate !== d.date) setDragOverDate(d.date);
                      }
                    }}
                    onDragLeave={() => {
                      if (dragOverDate === d.date) setDragOverDate(null);
                    }}
                    onDrop={(e) => {
                      e.preventDefault();
                      if (draggingRow && d.date) {
                        const rowId = draggingRow;
                        setDraggingRow(null);
                        setDragOverDate(null);
                        void setRowDate(rowId, d.date);
                      }
                    }}
                  >
                    <div className="flex items-center justify-between px-1.5 py-1">
                      {d.day !== null && (
                        <span
                          className={cn(
                            "flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[11px]",
                            isToday
                              ? "bg-brand-500 font-semibold text-white"
                              : isWeekend
                                ? "text-neutral-400 dark:text-neutral-500"
                                : "text-neutral-700 dark:text-neutral-200",
                          )}
                        >
                          {d.day}
                        </span>
                      )}
                      {date && (
                        <button
                          className="hidden rounded p-0.5 text-neutral-400 hover:bg-neutral-200 hover:text-neutral-600 group-hover/row:inline-flex dark:text-neutral-500 dark:hover:bg-neutral-800 dark:hover:text-neutral-200"
                          onClick={() => addRowAtDate(date)}
                          title={t("calendar.addRow")}
                        >
                          <Plus className="h-3 w-3" />
                        </button>
                      )}
                    </div>

                    <div className="flex min-h-0 flex-1 flex-col gap-1 px-1 pb-1">
                      {d.rows.map((row) => (
                        <CalCard
                          key={row.id}
                          row={row}
                          primaryField={visibleFields[0] ?? null}
                          visibleFields={visibleFields}
                          cells={cells}
                          dragging={draggingRow === row.id}
                          focused={focusRowId === row.id}
                          onDragStart={() => setDraggingRow(row.id)}
                          onDragEnd={() => {
                            if (draggingRow === row.id) setDraggingRow(null);
                            if (dragOverDate === d.date) setDragOverDate(null);
                          }}
                          onOpenDetail={() => void openRowDetail(row, source)}
                        />
                      ))}
                    </div>

                    {date && d.rows.length < 3 && (
                      <button
                        className="absolute inset-x-1 bottom-1 hidden rounded px-1 py-0.5 text-[10px] text-neutral-400 hover:bg-neutral-100 hover:text-neutral-600 group-hover/row:block dark:text-neutral-500 dark:hover:bg-neutral-800 dark:hover:text-neutral-200"
                        onClick={() => addRowAtDate(date)}
                      >
                        + {t("calendar.addRow")}
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {rowDetail && <RowDetailPanel row={rowDetail.row} view={rowDetail.view} onClose={closeRowDetail} />}
    </div>
  );
}

function pad(n: number): string {
  return String(n).padStart(2, "0");
}

function CalCard(props: {
  row: { id: string; position: number };
  primaryField: DatabaseField | null;
  visibleFields: DatabaseField[];
  cells: Record<string, Record<string, CellValue>>;
  dragging: boolean;
  /** 搜索命中的卡片：滚动定位后短时高亮 */
  focused: boolean;
  onDragStart: () => void;
  onDragEnd: () => void;
  onOpenDetail: () => void;
}) {
  const { row, primaryField, visibleFields, cells, dragging, focused } = props;
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- cells 为按行稀疏映射，无单元格的行没有条目（运行时可能 undefined）
  const value = primaryField ? (cells[row.id]?.[primaryField.id] ?? null) : null;
  const title = primaryField
    ? formatCellValue(primaryField.field_type, value, parseFieldOptions(primaryField.options))
    : t("row.detailName", { n: row.position + 1 });

  // 副信息：只取前 1 个可见单/多选/数字（紧凑）
  const subField = visibleFields.slice(1, 3).find(
    (f) =>
      f.field_type === "single_select" ||
      f.field_type === "multi_select" ||
      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- cells 为按行稀疏映射，无单元格的行没有条目（运行时可能 undefined）
      (f.field_type === "checkbox" && cells[row.id]?.[f.id] === true) ||
      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- 同上
      (f.field_type === "number" && cells[row.id]?.[f.id] != null),
  );
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- 同上
  const sub = subField ? { field: subField, value: cells[row.id]?.[subField.id] ?? null } : null;

  return (
    <div
      data-row-id={row.id}
      draggable
      onDragStart={props.onDragStart}
      onDragEnd={props.onDragEnd}
      className={cn(
        "group/card cursor-grab overflow-hidden rounded border bg-white text-[11px] leading-tight shadow-sm transition active:cursor-grabbing dark:bg-neutral-800",
        dragging
          ? "opacity-40 ring-1 ring-brand-500"
          : "border-neutral-200 dark:border-neutral-700 hover:border-neutral-300 dark:hover:border-neutral-600 hover:shadow-sm",
        focused && ROW_FOCUS_CLASS,
      )}
    >
      <div className="flex items-center justify-between gap-0.5 px-1.5 py-1">
        <span className="min-w-0 flex-1 truncate font-medium text-neutral-800 dark:text-neutral-100">
          {title || <span className="text-neutral-300 dark:text-neutral-600">{t("board.cardNamePlaceholder")}</span>}
        </span>
        <button
          type="button"
          className="shrink-0 rounded p-0.5 text-neutral-400 opacity-0 transition group-hover/card:opacity-100 hover:bg-neutral-200 hover:text-brand-600"
          title={t("row.openDetail")}
          onMouseDown={(e) => e.preventDefault()}
          onClick={(e) => {
            e.stopPropagation();
            props.onOpenDetail();
          }}
        >
          <ExternalLink className="h-2.5 w-2.5" />
        </button>
      </div>
      {sub && (
        <div className="border-t border-neutral-100 px-1.5 py-0.5 dark:border-neutral-700">
          <CalSub field={sub.field} value={sub.value} />
        </div>
      )}
    </div>
  );
}

function CalSub({ field, value }: { field: DatabaseField; value: CellValue }) {
  if (field.field_type === "single_select" || field.field_type === "multi_select") {
    return <SelectChips field={field} value={value} compact />;
  }
  if (field.field_type === "checkbox") {
    return <span className="font-medium text-brand-600">✓</span>;
  }
  if (field.field_type === "number") {
    const txt = formatCellValue("number", value, parseFieldOptions(field.options));
    return txt ? <span className="text-neutral-500">{txt}</span> : null;
  }
  return null;
}

import { useEffect, useState } from "react";
import { viewApi } from "@/lib/db";
import { t } from "@/lib/i18n";
import { logger } from "@/lib/logger";
import { patchViewConfig, readViewConfig } from "@/lib/view-config";
import { toast } from "sonner";
import { createDatabaseStore } from "@/stores/database";
import { DatabaseStoreProvider } from "@/stores/database-context";
import { BoardView } from "./BoardView";
import { CalendarView } from "./CalendarView";
import { GridView } from "./GridView";
import { TimelineView } from "./TimelineView";
import { ViewChips } from "./ViewChips";
import type { View } from "@/types/models";

/**
 * 数据库页（多视图，阶段 2）：页面 = 宿主 view，页内可挂多个派生 view（grid/board/calendar）。
 *
 * 字段/行/单元格只属于宿主，派生 view 仅携带自己的显示配置（筛选/排序/分组字段），
 * 所以这里同时向下传两份 view：
 * - view：当前视图，作为 store 数据键与该视图配置的载体
 * - source：宿主页面，标题、重命名与行详情归属都挂在它上面
 */
export function DatabasePage({ view }: { view: View }) {
  const [rows, setRows] = useState<View[]>([view]);
  const [activeId, setActiveId] = useState(view.id);
  // 每个数据库页（含并排对照的每一栏）持有一份独立的数据 store：
  // 两栏同时打开不同数据库时各读各的字段/行/单元格，互不覆盖。
  const [store] = useState(createDatabaseStore);

  useEffect(() => {
    let alive = true;
    setRows([view]);
    setActiveId(view.id);
    viewApi
      .listForSource(view.id)
      .then((list) => {
        if (!alive) return;
        setRows(list.length > 0 ? list : [view]);
        // 上次停留的视图可能已被删除：校验存在后再恢复，否则回落到宿主
        const saved = readViewConfig(view).activeViewId;
        if (saved && list.some((v) => v.id === saved)) setActiveId(saved);
      })
      .catch((e: unknown) => {
        if (!alive) return;
        logger.error("database-page.list-views", e);
        toast.error(t("error.db", { message: String(e) }));
      });
    return () => {
      alive = false;
    };
    // view 是树快照，只有换页面才需要重取（改名等由本地 state 同步）
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.id]);

  // 宿主那一行以树快照为准：侧边栏改名后标签立刻跟上（重取只在换页时发生）
  const views = rows.map((v) => (v.id === view.id ? view : v));
  const active = views.find((v) => v.id === activeId) ?? views[0];

  const select = (id: string) => {
    setActiveId(id);
    patchViewConfig(view, { activeViewId: id });
  };

  const grid = views.find((v) => v.layout === "grid");
  const tabs = (
    <ViewChips
      source={view}
      views={views}
      activeId={active.id}
      onSelect={select}
      onCreated={(created) => {
        setRows((prev) => [...prev, created]);
        select(created.id);
      }}
      onRenamed={(id, name) => setRows((prev) => prev.map((v) => (v.id === id ? { ...v, name } : v)))}
      onDeleted={(id) => {
        setRows((prev) => prev.filter((v) => v.id !== id));
        if (id === active.id) select(view.id);
      }}
    />
  );

  if (active.layout === "board") {
    return (
      <DatabaseStoreProvider value={store}>
        <BoardView
          key={active.id}
          view={active}
          source={view}
          tabs={tabs}
          onGoGrid={grid ? () => select(grid.id) : undefined}
        />
      </DatabaseStoreProvider>
    );
  }
  if (active.layout === "calendar") {
    return (
      <DatabaseStoreProvider value={store}>
        <CalendarView
          key={active.id}
          view={active}
          source={view}
          tabs={tabs}
          onGoGrid={grid ? () => select(grid.id) : undefined}
        />
      </DatabaseStoreProvider>
    );
  }
  if (active.layout === "timeline") {
    return (
      <DatabaseStoreProvider value={store}>
        <TimelineView
          key={active.id}
          view={active}
          source={view}
          tabs={tabs}
          onGoGrid={grid ? () => select(grid.id) : undefined}
        />
      </DatabaseStoreProvider>
    );
  }
  return (
    <DatabaseStoreProvider value={store}>
      <GridView key={active.id} view={active} source={view} tabs={tabs} />
    </DatabaseStoreProvider>
  );
}

