/** Grid 数据库视图（说明书 10-M4）：表头 32px / 行 32px / 单元格聚焦蓝框（6.6 节） */
export function GridView({
  view,
  source,
  tabs,
}: {
  /** 当前视图：显示配置与数据的归属键（可能是宿主本身，也可能是派生视图） */
  view: View;
  /** 宿主页面：标题、重命名与行详情的父子归属都挂在它上面 */
  source: View;
  /** 顶栏左侧的视图标签栏（页内切换 grid/board/calendar） */
  tabs?: React.ReactNode;
}) {
  const store = useDbStore();
  const storeApi = useDbStoreApi();
  const { fields, rows, cells, loading, sorts, filters, filterMode, rowDetail } = store;
  const { closeRowDetail } = store;

  const [editing, setEditing] = useState<{ rowId: string; fieldId: string } | null>(null);
  const [renamingField, setRenamingField] = useState<string | null>(null);
  const [optionsEditorFor, setOptionsEditorFor] = useState<DatabaseField | null>(null);
  const [menuOpenFor, setMenuOpenFor] = useState<string | null>(null);
  const [filterOpen, setFilterOpen] = useState(false);
  const [sortOpen, setSortOpen] = useState(false);
  // 待确认删除的行（行删除不可撤销，先确认再落库）
  const [deleteRowTarget, setDeleteRowTarget] = useState<DatabaseRow | null>(null);
  // 多选行（序号列勾选框）：键为 rowId；实际生效集合每次按可见行求交，行被删/被筛走都不会残留
  const [checkedRows, setCheckedRows] = useState<Set<string>>(new Set());
  const [deleteSelectedOpen, setDeleteSelectedOpen] = useState(false);
  const [draggingField, setDraggingField] = useState<string | null>(null);
  const [draggingRow, setDraggingRow] = useState<string | null>(null);
  const [groupFieldId, setGroupFieldId] = useState<string | null>(() => readViewConfig(view).groupFieldId ?? null);
  // 键盘光标（↑↓←→/Tab 移动、Enter 编辑、Delete 清空、Esc 退出）
  const [cursor, setCursor] = useState<{ rowId: string; fieldId: string } | null>(null);
  const [aggregates, setAggregates] = useState<Record<string, AggregateFn>>(
    () => readViewConfig(view).aggregates ?? {},
  );
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  // CSV 导入：解析完成后先暂存，等用户在 CsvImportDialog 里确认各列类型再落库
  const [importPlan, setImportPlan] = useState<{
    fileName: string;
    headers: string[];
    types: FieldType[];
    /** 数据行（不含表头） */
    dataRows: string[][];
  } | null>(null);
  // TSV 粘贴的锚点：最近一次点击的可编辑单元格（粘贴从这里向右向下展开）
  const pasteAnchorRef = useRef<{ rowId: string; fieldId: string } | null>(null);

  useEffect(() => {
    store.load(view).catch((e: unknown) => logger.error("grid.load", e));
    setCheckedRows(new Set());
    setCursor(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.id]);

  // 列宽拖拽：拖拽期间直接改 <col> 宽度（纯 DOM，零重渲/零 IPC），mouseup 才落库一次
  const tableRef = useRef<HTMLTableElement | null>(null);
  const startColumnResize = (e: ReactMouseEvent, fieldId: string, startWidth: number) => {
    e.preventDefault();
    const col = tableRef.current?.querySelector<HTMLTableColElement>(`col[data-field-id="${fieldId}"]`);
    if (!col) return;
    const startX = e.clientX;
    const onMove = (ev: MouseEvent) => {
      col.style.width = clampColumnWidth(startWidth + ev.clientX - startX) + "px";
    };
    const onUp = (ev: MouseEvent) => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      const width = clampColumnWidth(startWidth + ev.clientX - startX);
      void store.setFieldWidth(fieldId, width).catch((err: unknown) => {
        col.style.width = ""; // 落库失败：去掉本地预览宽度，回退 store 旧值
        logger.error("set field width failed", err);
        toast.error(t("error.db", { message: String(err) }));
      });
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  };

  const visibleFields = useMemo(() => fields.filter((f) => f.is_hidden === 0), [fields]);
  // 名称列（主列）：position 最小且不可隐藏，作为行详情入口
  const primaryField: DatabaseField | null = visibleFields.length > 0 ? visibleFields[0] : null;

  // 关联/汇总要读目标库：把本表所有关联字段的目标视图拉进缓存（同一目标库只请求一次）
  const relationDbOf = useRelationDbs(fields);

  // 公式/汇总字段没有存储值：把求值结果提前算进一份"有效单元格"图，排序/列汇总/分组小计都读它，
  // 否则按这两列排序排不动（raw 恒为空值）、汇总恒为空。没有这类字段时直接复用原始 cells。
  const evaluatedCells = useMemo(
    () => computeEvaluatedCells(rows, cells, fields, relationDbOf),
    [rows, cells, fields, relationDbOf],
  );

  const displayRows = useMemo(() => {
    const filtered = applyFilters(rows, cells, filters, fields, filterMode);
    return sortRows(filtered, evaluatedCells, sorts);
  }, [rows, cells, evaluatedCells, filters, fields, filterMode, sorts]);

  // 底部汇总菜单的 rowIds：每次渲染都新建数组会让菜单里的 useMemo 全部失效
  const displayRowIds = useMemo(() => displayRows.map((r) => r.id), [displayRows]);

  // 多选：只认当前可见（筛选 + 排序后）且仍存在的行
  const selectedIds = useMemo(
    () => displayRows.filter((r) => checkedRows.has(r.id)).map((r) => r.id),
    [displayRows, checkedRows],
  );
  const allSelected = displayRows.length > 0 && selectedIds.length === displayRows.length;

  const toggleRowChecked = (rowId: string) => {
    setCheckedRows((prev) => {
      const next = new Set(prev);
      if (next.has(rowId)) next.delete(rowId);
      else next.add(rowId);
      return next;
    });
  };

  const toggleSelectAll = () => {
    setCheckedRows(allSelected ? new Set() : new Set(displayRows.map((r) => r.id)));
  };

  const deleteSelected = async () => {
    const ids = selectedIds;
    if (ids.length === 0) return;
    try {
      const n = await store.removeRows(ids);
      setCheckedRows(new Set());
      toast.success(t("row.deletedMany", { count: String(n) }));
    } catch (e) {
      logger.error("delete rows failed", e);
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const duplicateSelected = async () => {
    const ids = selectedIds;
    if (ids.length === 0) return;
    try {
      const created = await store.duplicateRows(ids);
      setCheckedRows(new Set());
      toast.success(t("row.duplicated", { count: String(created.length) }));
    } catch (e) {
      logger.error("duplicate rows failed", e);
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  // 分组字段被删除或改成不可分组的类型时，自动回落成不分组（配置留着，改回来还在）
  const groupField = useMemo(
    () => fields.find((f) => f.id === groupFieldId && canGroupBy(f)) ?? null,
    [fields, groupFieldId],
  );
  const groupableFields = useMemo(() => visibleFields.filter(canGroupBy), [visibleFields]);
  const groups = useMemo(
    () => (groupField ? groupRowsForGrid(displayRows, cells, groupField) : null),
    [groupField, displayRows, cells],
  );

  // 搜索命中定位：折叠键作 revision，命中行所在分组一展开就能重新定位
  const collapsedKey = groups ? [...collapsedGroups].join("|") : "";
  const { scrollerRef, focusRowId } = useRowFocus(collapsedKey);

  // ---------- 大表窗口化 ----------
  // 行高固定（td h-8），行数超阈值时只渲染视口附近的行，上下用占位行撑住滚动条；
  // 阈值以下走原路径，小表零行为变化。分组视图不窗口化（组头/小计参与纵向布局）。
  const tbodyRef = useRef<HTMLTableSectionElement | null>(null);
  const rowHeightRef = useRef(ROW_H_FALLBACK);
  const [win, setWin] = useState<{ start: number; end: number } | null>(null);
  const virtual = !groups && displayRows.length > VIRTUAL_MIN_ROWS;

  // 量出"数据区在滚动内容里的 y 偏移"再折算窗口：表头高度随缩放/字体变化，写死常量会越滚越偏
  const measureWindow = useCallback(() => {
    const el = scrollerRef.current;
    const body = tbodyRef.current;
    if (!el || !body) return;
    const first = body.querySelector<HTMLElement>("tr[data-row-id]");
    if (first?.offsetHeight) rowHeightRef.current = first.offsetHeight;
    const h = rowHeightRef.current;
    const dataTop = body.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop;
    const next = computeVirtualWindow({
      scrollTop: el.scrollTop,
      dataTop,
      clientHeight: el.clientHeight,
      total: displayRows.length,
      rowHeight: h,
    });
    setWin((prev) => (prev?.start === next.start && prev.end === next.end ? prev : next));
  }, [scrollerRef, displayRows.length]);

  useEffect(() => {
    if (!virtual) {
      setWin(null);
      return;
    }
    const el = scrollerRef.current;
    if (!el) return;
    measureWindow();
    const onScroll = () => measureWindow();
    el.addEventListener("scroll", onScroll, { passive: true });
    const ro = new ResizeObserver(() => measureWindow());
    ro.observe(el);
    return () => {
      el.removeEventListener("scroll", onScroll);
      ro.disconnect();
    };
  }, [virtual, measureWindow, scrollerRef]);

  // 命中行在窗口外时先滚过去，等下一帧 useRowFocus 的 DOM 查询才找得到它
  useEffect(() => {
    if (!focusRowId || !virtual) return;
    const idx = displayRows.findIndex((r) => r.id === focusRowId);
    const el = scrollerRef.current;
    const body = tbodyRef.current;
    if (idx < 0 || !el || !body) return;
    if (win && idx >= win.start && idx < win.end) return;
    const dataTop = body.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop;
    el.scrollTop = rowCenterScrollTop({
      dataTop,
      index: idx,
      rowHeight: rowHeightRef.current,
      clientHeight: el.clientHeight,
    });
  }, [focusRowId, virtual, displayRows, win, scrollerRef]);

  useEffect(() => {
    if (!focusRowId || !groups) return;
    const hit = groups.find((g) => g.rows.some((r) => r.id === focusRowId));
    if (!hit || !collapsedGroups.has(hit.key)) return;
    setCollapsedGroups((prev) => {
      const next = new Set(prev);
      next.delete(hit.key);
      return next;
    });
  }, [focusRowId, groups, collapsedGroups]);

  // 字段类型可能已经变了：历史选择不在候选里就回落成计数
  const aggregateOf = (field: DatabaseField) => normalizeAggregate(field.field_type, aggregates[field.id]);
  const hasAggregates = visibleFields.some((f) => aggregateOf(f));

  // ---------- 键盘导航 ----------
  /** 光标移动：越界即夹紧；虚拟窗口外的行先滚过去，渲染完成后再聚焦 */
  const moveCursorTo = (rowIndex: number, colIndex: number) => {
    const ri = Math.max(0, Math.min(displayRows.length - 1, rowIndex));
    const ci = Math.max(0, Math.min(visibleFields.length - 1, colIndex));
    if (displayRows.length === 0 || visibleFields.length === 0) return;
    const row = displayRows[ri];
    const field = visibleFields[ci];
    if (virtual && (ri < (win?.start ?? 0) || ri >= (win?.end ?? Infinity))) {
      const el = scrollerRef.current;
      const body = tbodyRef.current;
      if (el && body) {
        const dataTop = body.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop;
        el.scrollTop = rowCenterScrollTop({
          dataTop,
          index: ri,
          rowHeight: rowHeightRef.current,
          clientHeight: el.clientHeight,
        });
      }
    }
    setCursor({ rowId: row.id, fieldId: field.id });
  };

  // 光标落定后聚焦对应单元格；虚拟化下目标行可能还没渲染，重试几帧
  useEffect(() => {
    if (!cursor || editing) return;
    const el = scrollerRef.current;
    if (!el) return;
    let raf = 0;
    const attempt = (tries: number) => {
      const td = el.querySelector<HTMLElement>(cellSelector(cursor));
      if (td) {
        td.focus({ preventScroll: true });
        td.scrollIntoView({ block: "nearest", inline: "nearest" });
        return;
      }
      if (tries > 0) raf = requestAnimationFrame(() => attempt(tries - 1));
    };
    attempt(3);
    return () => cancelAnimationFrame(raf);
  }, [cursor, editing, scrollerRef]);

  // TSV 粘贴锚点跟随键盘光标：键盘选好位置后直接 Ctrl+V 就有落点
  useEffect(() => {
    if (!cursor) return;
    const field = visibleFields.find((f) => f.id === cursor.fieldId);
    if (field && !isReadonlyType(field.field_type)) pasteAnchorRef.current = cursor;
  }, [cursor, visibleFields]);

  const onGridKeyDown = (e: React.KeyboardEvent) => {
    if (editing || !cursor) return;
    const target = e.target;
    if (!(target instanceof HTMLElement) || !target.closest("td[data-cell-row]")) return;
    const ri = displayRows.findIndex((r) => r.id === cursor.rowId);
    const ci = visibleFields.findIndex((f) => f.id === cursor.fieldId);
    if (ri < 0 || ci < 0) return;
    const field = visibleFields.find((f) => f.id === cursor.fieldId);
    // 空单元格在 cells 里没有键，取值可能是 undefined；断言让这里如实反映
    const readCell = (rowId: string, fieldId: string): CellValue | undefined => {
      const rowCells = cells[rowId] as Record<string, CellValue> | undefined;
      return rowCells?.[fieldId];
    };
    switch (e.key) {
      case "ArrowUp":
        e.preventDefault();
        moveCursorTo(ri - 1, ci);
        break;
      case "ArrowDown":
        e.preventDefault();
        moveCursorTo(ri + 1, ci);
        break;
      case "ArrowLeft":
        e.preventDefault();
        moveCursorTo(ri, ci - 1);
        break;
      case "ArrowRight":
        e.preventDefault();
        moveCursorTo(ri, ci + 1);
        break;
      case "Tab": {
        // 行尾 Tab 跳到下一行行首（表格连续感）
        e.preventDefault();
        const next = ci + (e.shiftKey ? -1 : 1);
        if (next >= visibleFields.length) moveCursorTo(ri + 1, 0);
        else if (next < 0) moveCursorTo(ri - 1, visibleFields.length - 1);
        else moveCursorTo(ri, next);
        break;
      }
      case "Enter": {
        if (!field || isReadonlyType(field.field_type)) break;
        e.preventDefault();
        if (field.field_type === "checkbox") {
          void commitCell(cursor.rowId, field.id, readCell(cursor.rowId, field.id) !== true);
        } else {
          setEditing({ rowId: cursor.rowId, fieldId: field.id });
        }
        break;
      }
      case " ": {
        if (field?.field_type !== "checkbox") break;
        e.preventDefault();
        void commitCell(cursor.rowId, field.id, readCell(cursor.rowId, field.id) !== true);
        break;
      }
      case "Delete": {
        if (!field || isReadonlyType(field.field_type) || readCell(cursor.rowId, field.id) == null) break;
        e.preventDefault();
        void commitCell(cursor.rowId, field.id, null);
        break;
      }
      case "Escape":
        e.preventDefault();
        setCursor(null);
        if (target instanceof HTMLElement) target.blur();
        break;
    }
  };

  const changeGroupField = (id: string | null) => {
    setGroupFieldId(id);
    setCollapsedGroups(new Set());
    patchViewConfig(view, { groupFieldId: id ?? "" });
  };

  const changeAggregate = (fieldId: string, fn: AggregateFn | undefined) => {
    const next: Record<string, AggregateFn> = {};
    for (const [id, value] of Object.entries(aggregates)) if (id !== fieldId) next[id] = value;
    if (fn) next[fieldId] = fn;
    setAggregates(next);
    patchViewConfig(view, { aggregates: next });
  };

  const commitCell = useCallback(
    async (rowId: string, fieldId: string, value: CellValue) => {
      setEditing(null);
      try {
        await store.setCell(rowId, fieldId, value);
      } catch (e) {
        logger.error("set cell failed", e);
        toast.error(t("error.db", { message: String(e) }));
      }
    },

    [store],
  );

  // 表头单击：没排过 → 追加升序；升序 → 转降序；降序 → 取消该字段（其余字段保持）
  const cycleSort = (fieldId: string) => {
    const current = sorts.find((s) => s.field_id === fieldId);
    const next: SortSpec[] = !current
      ? [...sorts, { field_id: fieldId, dir: "asc" }]
      : current.dir === "asc"
        ? sorts.map((s) => (s.field_id === fieldId ? { ...s, dir: "desc" as const } : s))
        : sorts.filter((s) => s.field_id !== fieldId);
    store.setSorts(next);
  };

  const addRow = async () => {
    try {
      await store.addRow();
    } catch (e) {
      logger.error("add row failed", e);
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  // 字段拖拽排序（主列固定首位，只在其它列之间排序）
  const onFieldDrop = (targetId: string) => {
    if (!draggingField || draggingField === targetId) return;
    if (draggingField === primaryField?.id || targetId === primaryField?.id) return;
    // 全量重排（含隐藏列）：传 visibleFields 会把隐藏字段从 store.fields 里剔除
    const sortable = fields.filter((f) => f.id !== primaryField?.id).map((f) => f.id);
    const from = sortable.indexOf(draggingField);
    const to = sortable.indexOf(targetId);
    if (from < 0 || to < 0) return;
    sortable.splice(to, 0, sortable.splice(from, 1)[0]);
    void store.reorderFields([primaryField?.id, ...sortable].filter((id): id is string => Boolean(id)));
    setDraggingField(null);
  };

  // 行拖拽排序
  const onRowDrop = (targetId: string) => {
    if (!draggingRow || draggingRow === targetId) return;
    // 全量重排（store 顺序 = position 顺序）：传 displayRows 会把被筛选掉的行从 store.rows 里剔除
    const ids = rows.map((r) => r.id);
    const from = ids.indexOf(draggingRow);
    const to = ids.indexOf(targetId);
    if (from < 0 || to < 0) return;
    ids.splice(to, 0, ids.splice(from, 1)[0]);
    void store.reorderRows(ids);
    setDraggingRow(null);
  };

  // CSV 导出（公式列在导出前注入算好的值；只导出当前筛选/排序后的可见行）
  const exportCsv = async () => {
    try {
      const cellsWithFormula = { ...cells };
      for (const row of displayRows) {
        const rowCells = cells[row.id] ?? {};
        for (const f of fields) {
          if (f.field_type === "formula") {
            const v = computeFormula(f, rowCells, fields);
            if (v !== null) {
              cellsWithFormula[row.id] = { ...(cellsWithFormula[row.id] ?? {}), [f.id]: v };
            }
          } else if (f.field_type === "rollup") {
            const v = computeRollup(f, rowCells, fields, relationDbOf);
            if (v !== null) {
              cellsWithFormula[row.id] = { ...(cellsWithFormula[row.id] ?? {}), [f.id]: v };
            }
          } else if (f.field_type === "relation") {
            // 导出成行标题而不是行 id：导出的 CSV 才对人可读
            const db = relationDbOf(relationTarget(f) ?? "");
            const text = relationRowIds(rowCells[f.id] ?? null)
              .map((id) => (db ? relationRowLabel(db, id) : null) ?? id)
              .join("; ");
            cellsWithFormula[row.id] = { ...(cellsWithFormula[row.id] ?? {}), [f.id]: text };
          } else if (f.field_type === "reverse_relation") {
            // 反向关系无存储值：实时反查来源行并导出标题（同样对人可读）
            const ids = computeReverseRelation(row.id, f, relationDbOf) ?? [];
            const cfg = parseFieldOptions(f.options);
            const db = cfg.kind === "reverse_relation" ? relationDbOf(cfg.source_view_id) : undefined;
            const text = ids.map((id) => (db ? relationRowLabel(db, id) : null) ?? id).join("; ");
            if (text !== "") cellsWithFormula[row.id] = { ...(cellsWithFormula[row.id] ?? {}), [f.id]: text };
          }
        }
      }
      // 前置 BOM：Excel 打开 UTF-8 CSV 才不会把中文显示成乱码
      const content = "\uFEFF" + buildCsvExport(fields, displayRows, cellsWithFormula);
      const target = await save({
        defaultPath: (source.name || "export").replace(/[\\/:*?"<>|]/g, "_") + ".csv",
        filters: [{ name: "CSV", extensions: ["csv"] }],
      });
      if (!target) return;
      await invoke("write_text_file", { path: target, content });
      toast.success(t("csv.exported"));
    } catch (e) {
      logger.error("csv export failed", e);
      toast.error(t("error.csv", { message: String(e) }));
    }
  };

  // Excel/表格 TSV 剪贴板粘贴：从锚点单元格向右向下展开，行不够自动补行
  const onPasteTsv = async (e: React.ClipboardEvent) => {
    if (editing) return; // 编辑框里的粘贴走默认（单格文本）
    if (e.target instanceof HTMLElement && e.target.closest("input, textarea")) return;
    const text = e.clipboardData.getData("text/plain");
    if (!text || (!text.includes("\t") && !text.includes("\n"))) return;
    const grid = parseTsv(text);
    if (grid.length === 0 || grid[0].length === 0) return;
    const anchor = pasteAnchorRef.current;
    if (!anchor) {
      toast.info(t("csv.pasteNoAnchor"));
      return;
    }
    e.preventDefault();
    const startRow = displayRows.findIndex((r) => r.id === anchor.rowId);
    const startCol = visibleFields.findIndex((f) => f.id === anchor.fieldId);
    if (startRow < 0 || startCol < 0) return;
    try {
      let skipped = 0;
      // 预取行队列：现有行 + 粘贴时按需新建（一次 IPC 建全部缺行，不再逐行 await）
      const rowQueue: string[] = displayRows.slice(startRow).map((r) => r.id);
      const missingRows = grid.length - rowQueue.length;
      if (missingRows > 0) {
        const created = await store.addRows(missingRows);
        if (created.length !== missingRows) return;
        rowQueue.push(...created.map((r) => r.id));
      }
      // 单元格写入先攒后写：一次 cell_set_many 落整片粘贴（选项补建仍逐条，但那是低频路径）
      const updates: { rowId: string; fieldId: string; value: CellValue }[] = [];
      for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[i].length; j++) {
          const field: DatabaseField | undefined = visibleFields[startCol + j];
          // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- noUncheckedIndexedAccess 关闭使索引返回非空类型，但粘贴网格列数可能超出可见列，运行时会越界返回 undefined
          if (!field) {
            skipped++; // 超出最右列
            continue;
          }
          if (
            isReadonlyType(field.field_type) ||
            field.field_type === "relation" ||
            field.field_type === "attachment"
          ) {
            skipped++; // 公式/汇总/系统字段、关联字段与附件字段跳过（粘贴的文本无法直接对应行 id / 文件）
            continue;
          }
          if (field.field_type === "single_select" || field.field_type === "multi_select") {
            // 选择类单元格存选项 id：按名字解析，缺的选项就地补建（导出侧把 id 翻回名字，两边闭环）
            // 每格都取 store 最新字段：上一格补建的选项要参与下一格的解析，避免同名重复建选项
            const fresh = storeApi.getState().fields.find((f) => f.id === field.id) ?? field;
            const opts = parseFieldOptions(fresh.options);
            if (opts.kind !== "select") {
              skipped++;
              continue;
            }
            const { ids, missing } = resolveSelectRefs(field.field_type, grid[i][j], opts.options);
            for (const name of missing) {
              const created = await store.addSelectOption(field.id, name);
              if (created) ids.push(created);
              else skipped++;
            }
            updates.push({
              rowId: rowQueue[i],
              fieldId: field.id,
              value: field.field_type === "multi_select" ? ids : (ids[0] ?? null),
            });
            continue;
          }
          updates.push({
            rowId: rowQueue[i],
            fieldId: field.id,
            value: csvValueToCell(field.field_type, grid[i][j]),
          });
        }
      }
      // 选择类补建过选项时会刷新 fields，但 cells 只在这里写一次，顺序上不冲突
      await store.setCellsMany(updates);
      const filled = updates.length;
      if (filled > 0) toast.success(t("csv.pasted", { n: String(filled) }));
      if (skipped > 0) toast.warning(t("csv.pasteSkipped", { n: String(skipped) }));
    } catch (err) {
      logger.error("tsv paste failed", err);
      toast.error(t("error.csv", { message: String(err) }));
    }
  };

  // CSV 导入（新表）：先选文件并解析，再弹对话框让用户确认各列类型，确认后才落库
  const importCsv = async () => {
    try {
      const selected = await open({
        multiple: false,
        filters: [{ name: "CSV", extensions: ["csv"] }],
      });
      if (typeof selected !== "string") return;
      const text = await invoke<string>("read_text_file", { path: selected });
      const parsed = parseCsv(text);
      if (parsed.length === 0) {
        toast.error(t("csv.emptyFile"));
        return;
      }
      const { headers, types } = planImport(parsed);
      // 新表名取文件名
      const base =
        selected
          .split(/[\\/]/)
          .pop()
          ?.replace(/\.csv$/i, "") ?? "";
      const fileName = base.length > 0 ? base : t("csv.importDefaultName");
      setImportPlan({ fileName, headers, types, dataRows: parsed.slice(1) });
    } catch (e) {
      logger.error("csv import failed", e);
      toast.error(t("error.csv", { message: String(e) }));
    }
  };

  /** 用户确认字段类型后执行真正的导入：建视图 → 建字段/行 → csv_import。
   *  附件列把「候选文件名」在所选文件夹索引里匹配，命中的先复制进 assets/ 再写单元格。 */
  const runImportCsv = async (types: FieldType[], foldersByColumn: Record<number, Record<string, string>>) => {
    const plan = importPlan;
    setImportPlan(null);
    if (!plan) return;
    try {
      const wsId = useWorkspaceStore.getState().currentWorkspaceId;
      if (!wsId) return;
      // 新表 = 新 grid 视图
      const newView = await viewApi.create({
        workspace_id: wsId,
        parent_id: null,
        name: plan.fileName,
        layout: "grid",
      });
      // 建字段（重名则加序号）—— 解析/类型推断/消歧/id 生成在 JS，落库由 csv_import 单命令完成
      // 选择列：按列值收集去重选项名 → 生成 options（名 → id），单元格按名转 id 存
      const used = new Set<string>();
      const selectIdMaps: Record<number, Map<string, string>> = {};
      const fields = plan.headers.map((header, i) => {
        let name = header;
        while (used.has(name)) name = name + " 2";
        used.add(name);
        if (types[i] === "single_select" || types[i] === "multi_select") {
          const names = collectSelectNames(
            types[i],
            plan.dataRows.map((r) => r[i] ?? ""),
          );
          const { options, idByName } = buildSelectOptions(names);
          selectIdMaps[i] = idByName;
          return { id: newId(), name, field_type: types[i], options: JSON.stringify({ kind: "select", options }) };
        }
        return { id: newId(), name, field_type: types[i], options: null };
      });

      // 附件列：逐行解析候选名（纯函数），收集待复制文件（按源路径去重）
      const attachmentCols: number[] = [];
      fields.forEach((f, i) => {
        if (f.field_type === "attachment") attachmentCols.push(i);
      });
      const resolved: Record<number, { matched: { name: string; sourcePath: string }[]; missing: string[] }[]> = {};
      const pendingSources = new Set<string>();
      for (const col of attachmentCols) {
        const files = foldersByColumn[col] ?? {};
        resolved[col] = plan.dataRows.map((line) => {
          const r = resolveAttachmentNames(line[col] ?? "", files);
          for (const m of r.matched) pendingSources.add(m.sourcePath);
          return r;
        });
      }
      // 先按去重后的源路径各复制一次（有上限并发），缓存「源路径 → assets 相对路径」避免重复复制
      const relBySource = new Map<string, string>();
      await mapWithConcurrency([...pendingSources], 8, async (sourcePath) => {
        try {
          relBySource.set(sourcePath, await invoke<string>("save_asset", { sourcePath }));
        } catch (e) {
          // 单个文件复制失败只记日志，后续按未匹配处理，不中断整次导入
          logger.warn("csv-import.save_asset", "save_asset failed", sourcePath, e);
        }
      });

      const missingNames = new Set<string>();
      // 嵌套 payload 按 Rust 结构体声明的 snake_case 键传（同 mention_rebuild 契约）
      const rows = plan.dataRows.map((line, ri) => {
        const cells: { field_id: string; value: string }[] = [];
        for (let i = 0; i < fields.length; i++) {
          const raw = line[i] ?? "";
          if (raw.trim() === "") continue;
          if (fields[i].field_type === "attachment") {
            const refs: AttachmentRef[] = [];
            for (const m of resolved[i][ri].matched) {
              const path = relBySource.get(m.sourcePath);
              if (path) refs.push({ name: m.name, path });
              else missingNames.add(m.name);
            }
            for (const name of resolved[i][ri].missing) missingNames.add(name);
            if (refs.length === 0) continue;
            cells.push({ field_id: fields[i].id, value: JSON.stringify(refs) });
            continue;
          }
          if (fields[i].field_type === "single_select" || fields[i].field_type === "multi_select") {
            const cell = selectCellToIds(fields[i].field_type, raw, selectIdMaps[i]);
            if (cell !== null) cells.push({ field_id: fields[i].id, value: JSON.stringify(cell) });
            continue;
          }
          const cell = csvValueToCell(fields[i].field_type, raw);
          if (cell !== null) cells.push({ field_id: fields[i].id, value: JSON.stringify(cell) });
        }
        return { id: newId(), cells };
      });
      await invoke("csv_import", { viewId: newView.id, fields, rows });
      await useWorkspaceStore.getState().reload();
      useWorkspaceStore.getState().openView(newView.id);
      toast.success(t("csv.imported", { count: String(plan.dataRows.length) }));
      if (missingNames.size > 0) {
        const names = [...missingNames];
        const shown = names.slice(0, 5).join(", ") + (names.length > 5 ? ` …(+${names.length - 5})` : "");
        toast.warning(t("csv.attachment.missingToast", { n: String(names.length), names: shown }));
      }
    } catch (e) {
      logger.error("csv import failed", e);
      toast.error(t("error.csv", { message: String(e) }));
    }
  };

  // 单行渲染：不分组时顺序铺开，分组时按组铺开（组内顺序沿用当前视图排序）
  // 行内容搬到 grid-row.tsx（普通函数而非组件，调用方式与行为与原内联 renderRow 一致）
  const rowCtx: GridRowContext = {
    store,
    source,
    visibleFields,
    primaryField,
    editing,
    cells,
    fields,
    relationDbOf,
    checkedRows,
    focusRowId,
    draggingRow,
    setDraggingRow,
    onRowDrop,
    toggleRowChecked,
    setDeleteRowTarget,
    commitCell,
    setCursor,
    setEditing,
    pasteAnchorRef,
  };
  const renderRow = (row: DatabaseRow) => renderGridRow(row, rowCtx);

  const toggleGroup = (key: string) => {
    const next = new Set(collapsedGroups);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    setCollapsedGroups(next);
  };

  if (loading && fields.length === 0) {
    return <div className="flex h-full items-center justify-center text-sm text-neutral-500">{t("app.loading")}</div>;
  }

  return (
    <div className="relative flex h-full flex-col overflow-hidden bg-white">
      {/* 顶栏（说明书 6.2：高 44px）：左侧是页内视图切换（宿主 chip 双击即重命名页面），
          页面名已由侧边栏/标签页承载，这里不再重复 */}
      <div className="flex h-11 shrink-0 items-center gap-2 border-b border-neutral-200 px-6">
        <div className="flex min-w-0 flex-1 items-center">{tabs}</div>
        <div className="flex shrink-0 items-center gap-1">
          {/* 多选操作条：勾了行才出现，避免常驻占位 */}
          {selectedIds.length > 0 && (
            <div className="mr-1 flex items-center gap-1 rounded-md border border-brand-200 bg-brand-50 px-2 py-0.5 text-xs text-brand-700 dark:border-brand-500/40 dark:bg-brand-500/10 dark:text-brand-300">
              <span data-testid="selected-count">{t("row.selected", { count: String(selectedIds.length) })}</span>
              <Button variant="ghost" size="sm" onClick={duplicateSelected}>
                <Copy className="h-3.5 w-3.5" />
                {t("row.duplicateSelected")}
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="text-red-600 hover:bg-red-100 hover:text-red-600 dark:text-red-400 dark:hover:bg-red-500/10"
                onClick={() => setDeleteSelectedOpen(true)}
              >
                <Trash2 className="h-3.5 w-3.5" />
                {t("row.deleteSelected")}
              </Button>
              <button
                className="flex h-5 w-5 items-center justify-center rounded text-brand-500 hover:bg-brand-100 dark:hover:bg-brand-500/20"
                title={t("row.selectionClear")}
                onClick={() => setCheckedRows(new Set())}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          )}
          {/* 分组字段切换 */}
          {groupableFields.length > 0 && (
            <div className="flex items-center gap-1.5 rounded-md border border-neutral-300 bg-white px-2 py-1 text-xs text-neutral-700">
              <span className="text-neutral-500">{t("grid.groupBy")}:</span>
              <select
                className="bg-transparent text-xs outline-none"
                value={groupFieldId ?? ""}
                onChange={(e) => changeGroupField(e.target.value || null)}
              >
                <option value="">{t("grid.noGroup")}</option>
                {groupableFields.map((f) => (
                  <option key={f.id} value={f.id}>
                    {f.name}
                  </option>
                ))}
              </select>
            </div>
          )}
          <HiddenColumnsMenu fields={fields} onShow={(id) => void store.toggleFieldHidden(id)} />
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setFilterOpen((v) => !v)}
            className={cn(filterOpen && "bg-brand-100 text-brand-600")}
          >
            <Filter className="h-3.5 w-3.5" />
            {t("filter.title")}
            {filters.length > 0 && (
              <span className="ml-1 rounded-full bg-brand-500 px-1.5 text-[10px] text-white">{filters.length}</span>
            )}
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setSortOpen((v) => !v)}
            className={cn(sortOpen && "bg-brand-100 text-brand-600")}
          >
            <ArrowUpDown className="h-3.5 w-3.5" />
            {t("sort.title")}
            {sorts.length > 0 && (
              <span className="ml-1 rounded-full bg-brand-500 px-1.5 text-[10px] text-white">{sorts.length}</span>
            )}
          </Button>
          <Button variant="ghost" size="sm" onClick={importCsv}>
            <FileUp className="h-3.5 w-3.5" />
            {t("csv.import")}
          </Button>
          <Button variant="ghost" size="sm" onClick={exportCsv}>
            <Download className="h-3.5 w-3.5" />
            {t("csv.export")}
          </Button>
        </div>
      </div>

      {filterOpen && (
        <FilterBar
          fields={fields}
          filters={filters}
          mode={filterMode}
          onChange={store.setFilters}
          onClose={() => setFilterOpen(false)}
        />
      )}

      {sortOpen && (
        <SortBar fields={fields} sorts={sorts} onChange={store.setSorts} onClose={() => setSortOpen(false)} />
      )}

      {/* 表格（横向滚动；TSV 剪贴板粘贴见 onPasteTsv） */}
      <div
        ref={scrollerRef}
        className="min-h-0 flex-1 overflow-auto outline-none"
        onPaste={(e) => void onPasteTsv(e)}
        onKeyDown={onGridKeyDown}
      >
        <table ref={tableRef} className="border-separate border-spacing-0">
          <colgroup>
            <col style={{ width: 44 }} />
            {visibleFields.map((f) => (
              <col key={f.id} data-field-id={f.id} style={{ width: f.width }} />
            ))}
            <col style={{ width: 44 }} />
          </colgroup>
          <thead>
            <tr>
              <th className="sticky left-0 z-[6] border-b border-r border-neutral-200 bg-neutral-100 px-2 text-[11px] font-normal text-neutral-500 dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-400">
                <button
                  className="mx-auto flex h-4 w-4 items-center justify-center rounded text-neutral-500 hover:text-brand-600 dark:text-neutral-400"
                  title={t("row.selectAll")}
                  onClick={toggleSelectAll}
                >
                  {allSelected ? (
                    <CheckSquare className="h-3.5 w-3.5 text-brand-600" />
                  ) : (
                    <Square className="h-3 w-3" />
                  )}
                </button>
              </th>
              {visibleFields.map((field) => {
                const sortIndex = sorts.findIndex((s) => s.field_id === field.id);
                const sort = sortIndex === -1 ? null : sorts[sortIndex];
                const isPrimary = field.id === primaryField?.id;
                return (
                  <th
                    key={field.id}
                    className={cn(
                      "group/head relative border-b border-r border-neutral-200 bg-neutral-100 px-1 dark:border-neutral-700 dark:bg-neutral-800",
                      // 冻结主列表头：z 高于正文 sticky 列
                      isPrimary && "sticky left-[44px] z-[6]",
                    )}
                  >
                    <div
                      draggable={field.id !== primaryField?.id}
                      onDragStart={() => {
                        if (field.id !== primaryField?.id) setDraggingField(field.id);
                      }}
                      onDragEnd={() => setDraggingField(null)}
                      onDragOver={(e) => {
                        if (draggingField && draggingField !== field.id && field.id !== primaryField?.id)
                          e.preventDefault();
                      }}
                      onDrop={(e) => {
                        e.preventDefault();
                        onFieldDrop(field.id);
                      }}
                      className={cn(
                        "flex h-8 cursor-pointer items-center gap-1",
                        draggingField === field.id && "opacity-40",
                      )}
                      onClick={() => cycleSort(field.id)}
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        setMenuOpenFor(field.id);
                      }}
                    >
                      <GripVertical className="h-3 w-3 shrink-0 cursor-grab text-neutral-300 dark:text-neutral-600" />
                      <span className="min-w-0 flex-1 truncate text-[12px] font-medium text-neutral-800 dark:text-neutral-100">
                        {field.name}
                      </span>
                      <span className="flex h-4 min-w-4 shrink-0 items-center justify-center gap-0.5 text-[10px] text-brand-600 dark:text-brand-500">
                        {sort && (
                          <>
                            <span>{sort.dir === "asc" ? "↑" : "↓"}</span>
                            {sorts.length > 1 && (
                              <span className="text-[9px] text-neutral-400 dark:text-neutral-500">{sortIndex + 1}</span>
                            )}
                          </>
                        )}
                      </span>
                      <FieldMenu
                        fieldName={field.name}
                        fieldType={field.field_type}
                        hidden={field.is_hidden === 1}
                        primary={field.id === primaryField?.id}
                        open={menuOpenFor === field.id}
                        onOpenChange={(open) => {
                          setMenuOpenFor(open ? field.id : null);
                        }}
                        onRename={() => {
                          setMenuOpenFor(null);
                          setRenamingField(field.id);
                        }}
                        onChangeType={(type) => {
                          setMenuOpenFor(null);
                          void store.changeFieldType(field.id, type).then(() => {
                            // 改成关联/公式/汇总后必须配置才有意义，直接弹出字段设置
                            if (!needsFieldSettings(type)) return;
                            const next = storeApi.getState().fields.find((f) => f.id === field.id);
                            if (next) setOptionsEditorFor(next);
                          });
                        }}
                        onToggleHidden={() => {
                          setMenuOpenFor(null);
                          void store.toggleFieldHidden(field.id);
                        }}
                        onDelete={() => {
                          setMenuOpenFor(null);
                          void store.removeField(field.id);
                        }}
                        onOpenOptions={() => {
                          setMenuOpenFor(null);
                          setOptionsEditorFor(field);
                        }}
                      />
                    </div>
                    {/* 重命名输入 */}
                    {renamingField === field.id && (
                      <RenameInput
                        initial={field.name}
                        onCommit={(name) => {
                          setRenamingField(null);
                          if (name && name !== field.name) void store.renameField(field.id, name);
                        }}
                        onCancel={() => setRenamingField(null)}
                      />
                    )}
                    {/* 列宽拖拽手柄 */}
                    <div
                      data-testid={"resize-" + field.id}
                      className="absolute right-0 top-0 h-full w-1 cursor-col-resize hover:bg-brand-500/60"
                      onMouseDown={(e) => startColumnResize(e, field.id, field.width)}
                    />
                  </th>
                );
              })}
              <th className="border-b border-neutral-200 bg-neutral-100 dark:border-neutral-700 dark:bg-neutral-800">
                <AddFieldButton onConfigure={setOptionsEditorFor} />
              </th>
            </tr>
          </thead>
          <tbody ref={tbodyRef}>
            {groups
              ? groups.map((group) => {
                  const collapsed = collapsedGroups.has(group.key);
                  return (
                    <Fragment key={group.key}>
                      <GridGroupHeaderRow
                        label={group.key === UNGROUPED || !group.label ? t("grid.ungrouped") : group.label}
                        count={group.rows.length}
                        collapsed={collapsed}
                        onToggle={() => toggleGroup(group.key)}
                        colSpan={visibleFields.length + 2}
                      />
                      {!collapsed && group.rows.map(renderRow)}
                      {!collapsed && hasAggregates && (
                        <GridSubtotalRow
                          rowIds={group.rows.map((r) => r.id)}
                          visibleFields={visibleFields}
                          aggregateOf={aggregateOf}
                          cells={evaluatedCells}
                        />
                      )}
                    </Fragment>
                  );
                })
              : virtual
                ? (() => {
                    // 首次 commit 还没量过窗口：先渲染开头一段，effect 量完立刻纠正
                    const start = win?.start ?? 0;
                    const end = win?.end ?? Math.min(displayRows.length, VIRTUAL_OVERSCAN * 4);
                    return (
                      <>
                        {start > 0 && (
                          <GridSpacerRow height={start * rowHeightRef.current} colSpan={visibleFields.length + 2} />
                        )}
                        {displayRows.slice(start, end).map(renderRow)}
                        {end < displayRows.length && (
                          <GridSpacerRow
                            height={(displayRows.length - end) * rowHeightRef.current}
                            colSpan={visibleFields.length + 2}
                          />
                        )}
                      </>
                    );
                  })()
                : displayRows.map(renderRow)}
            {/* 新建行：跨整行底部，避免无字段时挤在窄列里 */}
            <GridAddRow colSpan={1 + visibleFields.length + 1} onAdd={addRow} />
          </tbody>
          {/* 底部汇总行：每列一个可点的汇总函数，就地显示结果（无边框，与数据区视觉分离） */}
          <tfoot>
            <tr>
              <td className="px-1 pt-1 text-right text-[11px] text-neutral-400">{t("grid.total")}</td>
              {visibleFields.map((field, index) => (
                <td key={field.id} className="h-8 p-0 align-middle">
                  {(hasAggregates || index === 0) && (
                    <AggregateMenu
                      field={field}
                      fn={aggregateOf(field)}
                      rowIds={displayRowIds}
                      cells={evaluatedCells}
                      onPick={(fn) => changeAggregate(field.id, fn)}
                    />
                  )}
                </td>
              ))}
              <td />
            </tr>
          </tfoot>
        </table>
      </div>

      {optionsEditorFor && (
        <FieldOptionsEditor
          field={optionsEditorFor}
          open
          onOpenChange={(open) => {
            if (!open) setOptionsEditorFor(null);
          }}
          onSave={(opts) => void store.updateFieldOptions(optionsEditorFor.id, opts)}
        />
      )}

      <ConfirmDialog
        open={deleteRowTarget !== null}
        onOpenChange={(open) => {
          if (!open) setDeleteRowTarget(null);
        }}
        title={t("row.deleteConfirmTitle")}
        description={t("row.deleteConfirmDesc")}
        confirmLabel={t("common.delete")}
        onConfirm={() => {
          const row = deleteRowTarget;
          setDeleteRowTarget(null);
          if (!row) return;
          store
            .removeRow(row.id)
            .then(() => toast.success(t("row.deleted")))
            .catch((e: unknown) => toast.error(t("error.db", { message: String(e) })));
        }}
      />

      <ConfirmDialog
        open={deleteSelectedOpen}
        onOpenChange={setDeleteSelectedOpen}
        title={t("row.deleteSelectedConfirmTitle")}
        description={t("row.deleteSelectedConfirmDesc", { count: String(selectedIds.length) })}
        confirmLabel={t("common.delete")}
        onConfirm={() => void deleteSelected()}
      />

      {/* CSV 导入确认：逐列选类型 + 附件列选文件夹（取消则不建视图） */}
      {importPlan && (
        <CsvImportDialog
          headers={importPlan.headers}
          initialTypes={importPlan.types}
          dataRows={importPlan.dataRows}
          onCancel={() => setImportPlan(null)}
          onConfirm={(types, foldersByColumn) => void runImportCsv(types, foldersByColumn)}
        />
      )}

      {/* 行详情右侧滑出面板（说明书 6.1：宽 400px） */}
      {rowDetail && <RowDetailPanel row={rowDetail.row} view={rowDetail.view} onClose={closeRowDetail} />}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { useDbStore } from "@/stores/database-context";
import { applyFilters, sortRows } from "@/lib/database-query";
import { defaultCalendarField, rowDateKey } from "@/lib/board-calendar";
import { formatCellValue, parseFieldOptions } from "@/lib/database-values";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { t } from "@/lib/i18n";
import { logger } from "@/lib/logger";
import { patchViewConfig, readViewConfig } from "@/lib/view-config";
import {
  DAY_MS,
  autoScale,
  buildAxis,
  floorToScale,
  msToDateKey,
  parseDateKey,
  pointerToDayMs,
  type Scale,
  type ScaleMode,
} from "@/lib/timeline";
import { ROW_FOCUS_CLASS, useRowFocus } from "./rowFocus";
import { RowDetailPanel } from "./RowDetail";
import type { DatabaseRow } from "@/types/database";
import type { View } from "@/types/models";

// 时间线视图：一条横向时间轴 + 每行按日期落位。
// 开始日期字段决定落点；再选一个结束日期字段则画成横跨的条，否则只画点。
// 「本视图用哪个日期字段」这类配置写在 views.extra（view-config 的 timelineStartFieldId /
// timelineEndFieldId），与日历的 calendarFieldId 同一套机制。
// 日期/刻度纯逻辑见 @/lib/timeline（可单测）。
// v2 交互：拖动点/条改开始日期（条整体拖动保持时长不变），拖条右缘改结束日期；
// 仅当字段类型为 date 时可写（created_at/last_edited_at 只读，拖了不生效）。

/** Timeline 时间线视图：横向时间轴，支持拖拽改期（条可拖整体或拖右缘） */
export function TimelineView({
  view,
  source,
  tabs,
  onGoGrid,
}: {
  /** 当前视图：日期字段等显示配置的归属 */
  view: View;
  /** 宿主页面：标题、重命名与行详情的父子归属 */
  source: View;
  /** 顶栏左侧的视图标签栏（页内切换 grid/board/calendar/timeline） */
  tabs?: React.ReactNode;
  /** 无日期字段时引导回到表格视图 */
  onGoGrid?: () => void;
}) {
  const store = useDbStore();
  const { fields, rows, cells, loading, sorts, filters, filterMode, rowDetail } = store;
  const { openRowDetail, closeRowDetail } = store;

  const [startFieldId, setStartFieldId] = useState<string | null>(
    () => readViewConfig(view).timelineStartFieldId ?? null,
  );
  const [endFieldId, setEndFieldId] = useState<string | null>(() => readViewConfig(view).timelineEndFieldId ?? null);
  const [scaleMode, setScaleMode] = useState<ScaleMode>("auto");

  useEffect(() => {
    store.load(view).catch((e: unknown) => logger.error("timeline.load", e));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.id]);

  const dateFields = useMemo(
    () => fields.filter((f) => ["date", "created_at", "last_edited_at"].includes(f.field_type)),
    [fields],
  );
  const visibleFields = useMemo(() => fields.filter((f) => f.is_hidden === 0), [fields]);
  const primaryField = visibleFields.length > 0 ? visibleFields[0] : null;

  // 初始化开始日期字段：第一个 date/created_at/last_edited_at
  useEffect(() => {
    if (dateFields.length === 0) return;
    if (startFieldId && dateFields.some((f) => f.id === startFieldId)) return;
    setStartFieldId(defaultCalendarField(fields)?.id ?? null);
  }, [fields, dateFields, startFieldId]);

  // 结束日期字段失效（被删/改类型）时清空
  useEffect(() => {
    if (endFieldId && !dateFields.some((f) => f.id === endFieldId)) setEndFieldId(null);
  }, [dateFields, endFieldId]);

  const startField = fields.find((f) => f.id === startFieldId) ?? null;
  const endField = fields.find((f) => f.id === endFieldId) ?? null;

  const changeStartField = (id: string | null) => {
    setStartFieldId(id);
    patchViewConfig(view, { timelineStartFieldId: id ?? "" });
    // 结束字段与开始字段撞车时清掉，避免同一字段既当起又当止
    if (id && endFieldId === id) {
      setEndFieldId(null);
      patchViewConfig(view, { timelineEndFieldId: "" });
    }
  };
  const changeEndField = (id: string | null) => {
    setEndFieldId(id);
    patchViewConfig(view, { timelineEndFieldId: id ?? "" });
  };

  // 复用日历的取数方式：先筛后排序，再按日期落位
  const displayRows = useMemo(() => {
    const filtered = applyFilters(rows, cells, filters, fields, filterMode);
    return sortRows(filtered, cells, sorts);
  }, [rows, cells, filters, fields, filterMode, sorts]);

  const entries = useMemo(() => {
    if (!startField) return [];
    return displayRows.flatMap((row) => {
      const sk = rowDateKey(row, cells, startField.id);
      let s = sk ? parseDateKey(sk) : null;
      if (s === null) return [];
      const ek = endField ? rowDateKey(row, cells, endField.id) : null;
      let e = ek ? parseDateKey(ek) : s;
      e ??= s;
      if (e < s) [s, e] = [e, s];
      return [{ row, startMs: s, endMs: e }];
    });
  }, [displayRows, cells, startField, endField]);

  const range = useMemo(() => {
    if (entries.length === 0) return null;
    let min = Infinity;
    let max = -Infinity;
    for (const e of entries) {
      if (e.startMs < min) min = e.startMs;
      if (e.endMs > max) max = e.endMs;
    }
    return { min, max };
  }, [entries]);

  const scale: Scale = scaleMode === "auto" ? autoScale(range ? (range.max - range.min) / DAY_MS : 0) : scaleMode;

  const axis = useMemo(() => {
    if (!range) return null;
    return buildAxis(range, scale);
  }, [range, scale]);

  const { scrollerRef, focusRowId } = useRowFocus(axis ? `${scale}:${axis.domainStart}:${axis.span}` : "empty");

  // ---- 拖拽改期（v2）----
  // 仅 date 类型字段可写：created_at 手动可改但语义上是历史值、last_edited_at 由触发器强制刷新，
  // 都不可拖。拖拽期间用 dragPreview 覆盖该行的起止做即时渲染，pointerup 时一次写入。
  const [dragPreview, setDragPreview] = useState<{ rowId: string; startMs: number; endMs: number } | null>(null);
  const suppressClickRef = useRef(false);
  const startWritable = startField?.field_type === "date";
  const endWritable = endField?.field_type === "date";
  // 整体拖动要同时写起止两列：选了结束字段但它不可写时，只挪开始日会改变时长，故禁用整体拖动
  const moveDraggable = startWritable && (!endField || endWritable);

  const beginDrag = (
    e: React.PointerEvent<HTMLElement>,
    entry: { row: DatabaseRow; startMs: number; endMs: number },
    mode: "move" | "resize",
  ) => {
    if (!axis || !startField) return;
    if (mode === "move" ? !moveDraggable : !(startWritable && endWritable)) return;
    e.preventDefault();
    e.stopPropagation();
    const track = e.currentTarget.closest("[data-track]")?.getBoundingClientRect();
    if (!track) return;
    const origin = { startMs: entry.startMs, endMs: entry.endMs };
    const startX = e.clientX;
    const axisRef = axis;
    let moved = false;
    let latest = { ...origin };
    const onMove = (ev: PointerEvent) => {
      // 4px 死区：轻微抖动仍按点击处理（打开行详情）
      if (!moved && Math.abs(ev.clientX - startX) < 4) return;
      moved = true;
      const dayMs = pointerToDayMs(ev.clientX, track, axisRef.domainStart, axisRef.span);
      if (mode === "move") {
        const delta = dayMs - origin.startMs;
        latest = { startMs: origin.startMs + delta, endMs: origin.endMs + delta };
      } else {
        latest = { startMs: origin.startMs, endMs: Math.max(dayMs, origin.startMs) };
      }
      setDragPreview({ rowId: entry.row.id, ...latest });
    };
    const onUp = () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      if (!moved) return;
      // 拖完紧跟的 click 要吞掉；若指针在元素外释放（click 不触发），下一拍自动过期
      suppressClickRef.current = true;
      setTimeout(() => {
        suppressClickRef.current = false;
      }, 0);
      setDragPreview(null);
      void (async () => {
        try {
          const updates: { rowId: string; fieldId: string; value: string }[] = [
            { rowId: entry.row.id, fieldId: startField.id, value: msToDateKey(latest.startMs) },
          ];
          if (endField && endWritable && latest.endMs !== origin.endMs) {
            updates.push({ rowId: entry.row.id, fieldId: endField.id, value: msToDateKey(latest.endMs) });
          }
          await store.setCellsMany(updates);
        } catch (err) {
          logger.error("timeline.drag", err);
        }
      })();
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
  };

  const openFromClick = (row: DatabaseRow) => {
    // 拖拽结束会触发一次 click，吞掉它，避免拖完误开详情面板
    if (suppressClickRef.current) {
      suppressClickRef.current = false;
      return;
    }
    void openRowDetail(row, source);
  };

  // 「今天」参考线：今天在轴域内才画
  const todayPct = useMemo(() => {
    if (!axis) return null;
    const t0 = floorToScale(Date.now(), "day");
    if (t0 < axis.domainStart || t0 >= axis.domainStart + axis.span) return null;
    return ((t0 - axis.domainStart) / axis.span) * 100;
  }, [axis]);

  const titleOf = (row: DatabaseRow): string => {
    if (!primaryField) return t("row.detailName", { n: row.position + 1 });
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- cells 为按行稀疏映射，无单元格的行没有条目（运行时可能 undefined）
    const value = cells[row.id]?.[primaryField.id] ?? null;
    return formatCellValue(primaryField.field_type, value, parseFieldOptions(primaryField.options));
  };

  if (loading && fields.length === 0) {
    return <div className="flex h-full items-center justify-center text-sm text-neutral-500">{t("app.loading")}</div>;
  }

  return (
    <div className="relative flex h-full flex-col overflow-hidden bg-white dark:bg-neutral-900">
      {/* 顶栏（44px，和 GridView 一致）：左侧为页内视图切换 */}
      <div className="flex h-11 shrink-0 items-center gap-2 border-b border-neutral-200 px-6 dark:border-neutral-700">
        <div className="flex min-w-0 flex-1 items-center">{tabs}</div>

        <div className="flex shrink-0 items-center gap-1">
          <div className="flex items-center gap-1.5 rounded-md border border-neutral-300 bg-white px-2 py-1 text-xs text-neutral-700 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-200">
            <span className="text-neutral-500 dark:text-neutral-400">{t("timeline.startField")}:</span>
            <select
              className="bg-transparent text-xs outline-none"
              value={startFieldId ?? ""}
              onChange={(e) => changeStartField(e.target.value || null)}
            >
              {dateFields.length === 0 && <option value="">{t("calendar.noField")}</option>}
              {dateFields.map((f) => (
                <option key={f.id} value={f.id}>
                  {f.name}
                </option>
              ))}
            </select>
          </div>

          {/* 结束日期字段：本表还存在其它日期字段时才可选，不选则只画点 */}
          {dateFields.length > 1 && (
            <div className="flex items-center gap-1.5 rounded-md border border-neutral-300 bg-white px-2 py-1 text-xs text-neutral-700 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-200">
              <span className="text-neutral-500 dark:text-neutral-400">{t("timeline.endField")}:</span>
              <select
                className="bg-transparent text-xs outline-none"
                value={endFieldId ?? ""}
                onChange={(e) => changeEndField(e.target.value || null)}
              >
                <option value="">{t("timeline.noEnd")}</option>
                {dateFields
                  .filter((f) => f.id !== startFieldId)
                  .map((f) => (
                    <option key={f.id} value={f.id}>
                      {f.name}
                    </option>
                  ))}
              </select>
            </div>
          )}

          <div className="flex items-center gap-1.5 rounded-md border border-neutral-300 bg-white px-2 py-1 text-xs text-neutral-700 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-200">
            <span className="text-neutral-500 dark:text-neutral-400">{t("timeline.scale")}:</span>
            <select
              className="bg-transparent text-xs outline-none"
              value={scaleMode}
              onChange={(e) => setScaleMode(e.target.value as ScaleMode)}
            >
              <option value="auto">{t("timeline.scaleAuto")}</option>
              <option value="day">{t("timeline.scaleDay")}</option>
              <option value="week">{t("timeline.scaleWeek")}</option>
              <option value="month">{t("timeline.scaleMonth")}</option>
            </select>
          </div>
        </div>
      </div>

      {!startField ? (
        <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 px-6 text-center">
          <div className="text-4xl">📆</div>
          <h2 className="text-base font-semibold text-neutral-800 dark:text-neutral-100">{t("timeline.noField")}</h2>
          <p className="max-w-md text-sm text-neutral-500 dark:text-neutral-400">{t("timeline.noFieldDesc")}</p>
          {onGoGrid && (
            <Button size="sm" onClick={onGoGrid}>
              {t("board.goGrid")}
            </Button>
          )}
        </div>
      ) : !axis ? (
        <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 px-6 text-center">
          <div className="text-4xl">📆</div>
          <h2 className="text-base font-semibold text-neutral-800 dark:text-neutral-100">{t("timeline.empty")}</h2>
          <p className="max-w-md text-sm text-neutral-500 dark:text-neutral-400">{t("timeline.noFieldDesc")}</p>
        </div>
      ) : (
        <div ref={scrollerRef} className="min-h-0 flex-1 overflow-auto">
          <div className="min-w-[720px]">
            {/* 轴标题行 */}
            <div className="flex border-b border-neutral-200 bg-neutral-100/60 text-[11px] text-neutral-500 dark:border-neutral-700 dark:bg-neutral-800/40 dark:text-neutral-400">
              <div className="w-44 shrink-0 border-r border-neutral-200 px-3 dark:border-neutral-700" />
              <div className="relative h-8 flex-1">
                {axis.ticks.map((tk, i) => (
                  <div key={i} className="absolute top-0 flex h-full items-center" style={{ left: `${tk.pct}%` }}>
                    <span className="-translate-x-1/2 whitespace-nowrap px-1">{tk.label}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* 每行一条轨道：有结束日期画条，否则画点；可拖拽改期 */}
            {entries.map((entry) => {
              const { row } = entry;
              const preview = dragPreview?.rowId === row.id ? dragPreview : null;
              const startMs = preview ? preview.startMs : entry.startMs;
              const endMs = preview ? preview.endMs : entry.endMs;
              const left = ((startMs - axis.domainStart) / axis.span) * 100;
              const width = ((endMs - startMs) / axis.span) * 100;
              const isSpan = endMs > startMs;
              const title = titleOf(row);
              const focused = focusRowId === row.id;
              const draggable = moveDraggable;
              return (
                <div key={row.id} className="flex border-b border-neutral-100 dark:border-neutral-800">
                  <div
                    className="w-44 shrink-0 truncate border-r border-neutral-200 px-3 py-2 text-xs text-neutral-700 dark:border-neutral-700 dark:text-neutral-200"
                    title={title}
                  >
                    {title || (
                      <span className="text-neutral-300 dark:text-neutral-600">{t("board.cardNamePlaceholder")}</span>
                    )}
                  </div>
                  <div data-track className="relative h-9 flex-1">
                    {/* 刻度线 */}
                    {axis.ticks.map((tk, i) => (
                      <div
                        key={i}
                        className="absolute inset-y-0 w-px bg-neutral-100 dark:bg-neutral-800"
                        style={{ left: `${tk.pct}%` }}
                      />
                    ))}
                    {/* 「今天」参考线 */}
                    {todayPct !== null && (
                      <div className="absolute inset-y-0 w-px bg-red-400/70" style={{ left: `${todayPct}%` }} />
                    )}
                    {isSpan ? (
                      <div
                        data-row-id={row.id}
                        role="button"
                        tabIndex={0}
                        className={cn(
                          "absolute top-1/2 h-5 -translate-y-1/2 overflow-visible rounded bg-brand-500 text-left text-[11px] font-medium text-white shadow-sm transition",
                          draggable ? "cursor-grab active:cursor-grabbing hover:bg-brand-600" : "hover:bg-brand-600",
                          focused && ROW_FOCUS_CLASS,
                          dragPreview?.rowId === row.id && "opacity-80",
                        )}
                        style={{ left: `${left}%`, width: `${Math.max(width, 1)}%` }}
                        onClick={() => openFromClick(row)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault();
                            openFromClick(row);
                          }
                        }}
                        onPointerDown={(e) => beginDrag(e, entry, "move")}
                        title={
                          draggable ? `${title || t("board.cardNamePlaceholder")}（${t("timeline.dragHint")}）` : title
                        }
                      >
                        <span className="block truncate rounded bg-brand-500 leading-5 px-2">
                          {title || t("board.cardNamePlaceholder")}
                        </span>
                        {startWritable && endWritable && (
                          <span
                            className="absolute inset-y-0 -right-1 w-2 cursor-ew-resize rounded-r bg-brand-700/60 hover:bg-brand-700"
                            onPointerDown={(e) => beginDrag(e, entry, "resize")}
                          />
                        )}
                      </div>
                    ) : (
                      <div
                        data-row-id={row.id}
                        role="button"
                        tabIndex={0}
                        className={cn(
                          "absolute top-1/2 flex -translate-y-1/2 items-center gap-1 rounded px-1 py-0.5 text-left text-[11px] text-neutral-700 transition hover:bg-neutral-100 dark:text-neutral-200 dark:hover:bg-neutral-800",
                          draggable && "cursor-grab active:cursor-grabbing",
                          focused && ROW_FOCUS_CLASS,
                          dragPreview?.rowId === row.id && "opacity-80",
                        )}
                        style={{ left: `${left}%` }}
                        onClick={() => openFromClick(row)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault();
                            openFromClick(row);
                          }
                        }}
                        onPointerDown={(e) => beginDrag(e, entry, "move")}
                        title={
                          draggable ? `${title || t("board.cardNamePlaceholder")}（${t("timeline.dragHint")}）` : title
                        }
                      >
                        <span className="-ml-[5px] h-2.5 w-2.5 shrink-0 rounded-full bg-brand-500" />
                        <span className="truncate">{title || t("board.cardNamePlaceholder")}</span>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {rowDetail && <RowDetailPanel row={rowDetail.row} view={rowDetail.view} onClose={closeRowDetail} />}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Hash } from "lucide-react";
import { useEditorStore } from "@/stores/editor";
import { useWorkspaceStore } from "@/stores/workspace";
import { t } from "@/lib/i18n";
import { findNode } from "@/lib/tree";

const SIDEBAR_TAB_KEY = "tsflowy:ui:sidebar_tab";

interface HeadingItem {
  pos: number;
  level: number;
  text: string;
  /** 对应的 <h1>..<h6> DOM 元素缓存（减少 DOM 查找次数） */
  cachedDom?: HTMLElement | null;
}

const TK = {
  panelTitle: "sidebar.tab.outline",
  noDocument: "sidebar.outline.noDocument",
  empty: "sidebar.outline.empty",
} as const;

/** 标题列表是否等价（pos/level/text 全等；忽略 cachedDom 缓存） */
function sameHeadings(a: HeadingItem[], b: HeadingItem[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i].pos !== b[i].pos || a[i].level !== b[i].level || a[i].text !== b[i].text) return false;
  }
  return true;
}

/**
 * 大纲侧栏 Tab（Phase 3.1）：
 *
 * 1. 从全局 useEditorStore 读取 editor（EditorPage 在挂载时推送，卸载时清空），
 *    不再依赖 props，让 Sidebar 兄弟节点也能访问。
 * 2. 仅当当前激活 view 是 document 布局时才采集 heading；其他布局（grid/board/calendar）
 *    显示"打开一个文档以查看大纲"占位提示。
 * 3. 点击条目 → 平滑滚动 editor 内容容器到该标题 + 光标定位（与原浮动版逻辑一致）。
 * 4. IntersectionObserver + 滚动 fallback 高亮当前可视区最靠上的标题。
 * 5. 内容直接内联渲染在 sidebar 容器内（不再 fixed 浮动）。
 */
export function DocumentOutline() {
  const editor = useEditorStore((s) => s.editor);
  const currentViewId = useEditorStore((s) => s.currentViewId);
  const tree = useWorkspaceStore((s) => s.tree);

  const currentView = currentViewId ? findNode(tree, currentViewId) : null;
  const isDocument = currentView?.layout === "document";

  const [headings, setHeadings] = useState<HeadingItem[]>([]);
  const [activePos, setActivePos] = useState<number | null>(null);
  const ioRef = useRef<IntersectionObserver | null>(null);
  const scrollElRef = useRef<Element | null>(null);
  const activeItemsRef = useRef<Map<Element, number>>(new Map());
  // 缓存 headings 引用，避免 effect 闭包陈旧
  const headingsRef = useRef<HeadingItem[]>([]);
  headingsRef.current = headings;

  // 收集 headings + 订阅 editor 更新与选区变化
  useEffect(() => {
    if (!editor || !isDocument) {
      setHeadings([]);
      setActivePos(null);
      return;
    }

    const collect = () => {
      const list: HeadingItem[] = [];
      editor.state.doc.descendants((node, pos) => {
        if (node.type.name === "heading") {
          const level = (node.attrs.level as number | undefined) ?? 1;
          const text = node.textContent.trim().replace(/\s+/g, " ") || "(Untitled)";
          list.push({ pos, level, text });
        }
      });
      // 引用不变 → 不触发重渲染，也避免下方 IntersectionObserver effect 在每次按键时重建
      setHeadings((prev) => (sameHeadings(prev, list) ? prev : list));
    };

    // 打字热路径：update 每个按键都触发，全文档遍历 + IO 重建代价高 → 节流到 ~200ms
    let timer: ReturnType<typeof setTimeout> | null = null;
    const scheduleCollect = () => {
      if (timer) return;
      timer = setTimeout(() => {
        timer = null;
        collect();
      }, 200);
    };

    const onSelectionChange = () => {
      const sel = editor.state.selection;
      let best: HeadingItem | null = null;
      for (const h of headingsRef.current) {
        if (h.pos <= sel.from) best = h;
        else break;
      }
      if (best) setActivePos(best.pos);
    };

    collect();
    editor.on("update", scheduleCollect);
    editor.on("selectionUpdate", onSelectionChange);
    return () => {
      if (timer) clearTimeout(timer);
      editor.off("update", scheduleCollect);
      editor.off("selectionUpdate", onSelectionChange);
    };
  }, [editor, isDocument]);

  // 找到 editor 内容的 overflow-y 父容器（EditorPage 编辑区外层 overflow-auto）
  useEffect(() => {
    if (!editor?.view.dom || !isDocument) {
      scrollElRef.current = null;
      return;
    }
    let el: Element | null = editor.view.dom;
    for (let i = 0; i < 8 && el; i++) {
      const ov = window.getComputedStyle(el).overflowY;
      if (ov === "auto" || ov === "scroll") break;
      el = el.parentElement;
    }
    scrollElRef.current = el ?? document.documentElement;
    return () => {
      scrollElRef.current = null;
    };
  }, [editor, isDocument]);

  // IntersectionObserver：监听每个 heading dom 进入视口
  useEffect(() => {
    if (!editor?.view.dom || !isDocument) return;

    if (typeof IntersectionObserver === "undefined") {
      const sc = scrollElRef.current;
      if (!sc) return;
      const handler = () => scrollFindActive();
      sc.addEventListener("scroll", handler, { passive: true });
      window.addEventListener("resize", handler);
      return () => {
        sc.removeEventListener("scroll", handler);
        window.removeEventListener("resize", handler);
      };
    }

    ioRef.current?.disconnect();
    activeItemsRef.current.clear();

    const io = new IntersectionObserver(
      (entries) => {
        let currentBest: { pos: number; top: number } | null = null;
        for (const e of entries) {
          const pos = activeItemsRef.current.get(e.target);
          if (pos === undefined) continue;
          const rect = e.boundingClientRect;
          if (!e.isIntersecting) continue;
          const score = rect.top >= 0 ? rect.top : 10000 + Math.abs(rect.top);
          if (currentBest === null || score < currentBest.top) {
            currentBest = { pos, top: score };
          }
        }
        if (currentBest) setActivePos(currentBest.pos);
        else scrollFindActive();
      },
      {
        root: scrollElRef.current === document.documentElement ? null : scrollElRef.current,
        rootMargin: "-60px 0px -72% 0px",
        threshold: [0, 0.1, 1],
      },
    );
    ioRef.current = io;

    for (const h of headings) {
      const dom = findHeadingDom(editor, h.pos, headings);
      if (!dom) continue;
      activeItemsRef.current.set(dom, h.pos);
      io.observe(dom);
    }
    scrollFindActive();
    const activeItems = activeItemsRef.current;
    return () => {
      io.disconnect();
      activeItems.clear();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editor, isDocument, headings]);

  /** 兜底：遍历 headings DOM，找视口最上方那个 */
  function scrollFindActive() {
    if (!editor) return;
    const current = headingsRef.current;
    let best: { pos: number; top: number } | null = null;
    const containerRect =
      scrollElRef.current instanceof HTMLElement ? scrollElRef.current.getBoundingClientRect() : null;
    const baseTop = containerRect ? containerRect.top : 0;
    for (const h of current) {
      const dom = findHeadingDom(editor, h.pos, current);
      if (!dom) continue;
      const r = dom.getBoundingClientRect();
      const rel = r.top - baseTop;
      const metric = rel <= 0 ? -1000000 + rel : rel;
      if (best === null || metric < best.top) {
        best = { pos: h.pos, top: metric };
      }
    }
    if (best) setActivePos(best.pos);
  }

  /** 按 PM pos 找到 <h1>..<h6> DOM（含缓存） */
  function findHeadingDom(
    ed: { view: { domAtPos: (p: number) => { node: Node; offset: number } } },
    pos: number,
    list: HeadingItem[],
  ): HTMLElement | null {
    const cached = list.find((x) => x.pos === pos)?.cachedDom;
    if (cached !== undefined) return cached ?? null;
    try {
      const result = ed.view.domAtPos(pos + 1);
      let node: Node | null = result.node;
      while (node && node.nodeType !== 1) node = node.parentNode;
      let el = node as HTMLElement | null;
      while (el && !/^h[1-6]$/i.test(el.tagName)) {
        el = el.parentElement;
      }
      const item = list.find((x) => x.pos === pos);
      if (item) item.cachedDom = el ?? null;
      return el;
    } catch {
      return null;
    }
  }

  /** 点击：平滑滚动到该标题 + 光标定位 */
  function jumpTo(h: HeadingItem) {
    if (!editor) return;
    const dom = findHeadingDom(editor, h.pos, headingsRef.current);
    const sc = scrollElRef.current as HTMLElement | null;
    if (dom && sc) {
      const containerRect = sc.getBoundingClientRect();
      const r = dom.getBoundingClientRect();
      const targetScroll = sc.scrollTop + (r.top - containerRect.top) - 16;
      sc.scrollTo({ top: Math.max(0, targetScroll), behavior: "smooth" });
    } else if (dom) {
      dom.scrollIntoView({ block: "start", behavior: "smooth" });
    }
    editor
      .chain()
      .focus()
      .setTextSelection(h.pos + 1)
      .run();
    setActivePos(h.pos);
  }

  const indentBy = (level: number) => `${Math.max(0, Math.min(6, level) - 1) * 12}px`;
  const levelStyle = useMemo(
    () => (level: number) => {
      const sizes: Record<number, string> = {
        1: "text-[13px] font-semibold text-neutral-700",
        2: "text-[12.5px] font-medium text-neutral-700",
        3: "text-[12px] text-neutral-600",
      };
      return sizes[level] ?? "text-[12px] text-neutral-500";
    },
    [],
  );

  // 非文档视图：占位提示
  if (!isDocument) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center px-4 py-8 text-center">
        <Hash className="mb-2 h-5 w-5 text-neutral-300" />
        <p className="text-[12px] text-neutral-400">{t(TK.noDocument)}</p>
      </div>
    );
  }

  // 文档视图但无标题
  if (headings.length === 0) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center px-4 py-8 text-center">
        <Hash className="mb-2 h-5 w-5 text-neutral-300" />
        <p className="text-[12px] text-neutral-400">{t(TK.empty)}</p>
      </div>
    );
  }

  return (
    <nav className="flex-1 overflow-y-auto px-1 py-2" aria-label={t(TK.panelTitle)}>
      <ul className="space-y-0.5">
        {headings.map((h) => {
          const isActive = activePos === h.pos;
          return (
            <li key={h.pos}>
              <button
                type="button"
                onClick={() => jumpTo(h)}
                style={{ paddingLeft: indentBy(h.level) }}
                className={[
                  "group block w-full rounded-md border-l-2 px-2.5 py-1.5 pr-2 text-left transition",
                  isActive ? "border-brand-500 bg-brand-50 text-brand-800" : "border-transparent hover:bg-neutral-100",
                ].join(" ")}
              >
                <span
                  className={["block truncate", levelStyle(h.level), isActive ? "text-brand-800" : ""].join(" ")}
                  title={h.text}
                >
                  {h.text}
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

// ——————————————————————————————————————
// Sidebar Tab 切换状态持久化（小工具函数）
// 旧版 OUTLINE_STORAGE_KEY 已废弃，新 key 是 sidebar_tab（tree/outline/tags）。
// ——————————————————————————————————————
export type SidebarTab = "tree" | "outline" | "tags";

export function getSidebarTab(): SidebarTab {
  try {
    const v = localStorage.getItem(SIDEBAR_TAB_KEY);
    if (v === "outline" || v === "tags") return v;
  } catch {
    /* ignore */
  }
  return "tree";
}

export function setSidebarTab(v: SidebarTab): void {
  try {
    localStorage.setItem(SIDEBAR_TAB_KEY, v);
  } catch {
    /* ignore */
  }
}

import { useCallback, useEffect, useImperativeHandle, useRef, useState, type Ref } from "react";
import type { MentionOptions } from "@tiptap/extension-mention";
import { ReactRenderer } from "@tiptap/react";
import { FileText, Table2 } from "lucide-react";
import { viewIcon } from "@/components/view-icon";
import { useWorkspaceStore } from "@/stores/workspace";
import { flattenTree } from "@/lib/tree";
import { viewApi } from "@/lib/db";
import { databaseApi } from "@/lib/database";
import { newSelectOption } from "@/lib/database-values";
import type { View } from "@/types/models";
import { t } from "@/lib/i18n";
import { logger } from "@/lib/logger";
import { toast } from "sonner";

// —— 数据类型（@tiptap/extension-mention 自定义 item）——
export interface MentionItem {
  id: string; // viewId
  label: string; // 页面名
  view?: View;
}

// —— 提及下拉列表组件（Suggestion.render 里由 ReactRenderer 挂载）——
interface MentionListProps {
  items: MentionItem[];
  command: (item: MentionItem) => void;
  query: string;
  ref?: Ref<MentionListHandle>;
}

interface MentionListHandle {
  onKeyDown: (event: KeyboardEvent) => boolean;
}

export function MentionList(props: MentionListProps) {
  const { items, command, query, ref } = props;
  const [active, setActive] = useState(0);
  const listRef = useRef<HTMLDivElement>(null);

  // 搜索框值（显示当前 query，用户也可在其中输入来补充搜索）
  const [searchText, setSearchText] = useState(query);

  useEffect(() => setSearchText(query), [query]);

  // 客户端二次过滤（基于 searchText）
  const filteredItems = searchText.trim()
    ? items.filter((it) => it.label.toLowerCase().includes(searchText.toLowerCase()))
    : items;

  // 是否显示"新建"选项：列表为空且搜索词非空
  const showCreate = filteredItems.length === 0 && searchText.trim().length > 0;

  // 所有可选项（已有项 + 新建项）
  const allOptions = [...filteredItems];
  if (showCreate) {
    allOptions.push(
      { id: "__create_doc__", label: searchText.trim() },
      { id: "__create_table__", label: searchText.trim() },
    );
  }

  useEffect(() => setActive(0), [searchText, items, showCreate]);

  const onKeyDown = useCallback(
    (event: KeyboardEvent): boolean => {
      const len = Math.max(allOptions.length, 1);
      if (event.key === "ArrowDown") {
        setActive((a) => (a + 1) % len);
        return true;
      }
      if (event.key === "ArrowUp") {
        setActive((a) => (a - 1 + allOptions.length) % len);
        return true;
      }
      if (event.key === "Enter") {
        if (allOptions[active]) {
          handleSelect(allOptions[active]);
          return true;
        }
        return false;
      }
      return false;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [allOptions, active],
  );

  useImperativeHandle(ref, () => ({ onKeyDown }));

  useEffect(() => {
    listRef.current?.querySelector<HTMLElement>("[data-active='true']")?.scrollIntoView({ block: "nearest" });
  }, [active]);

  const handleCreateDoc = async (name: string) => {
    try {
      const ws = useWorkspaceStore.getState();
      const wsId = ws.currentWorkspaceId;
      if (!wsId) return;
      // 1. 创建视图（不走 store.createView 避免 reload 导致 editor 失效）
      const newView = await viewApi.create({ workspace_id: wsId, parent_id: null, name, layout: "document" });
      // 2. 先插入 mention 节点（此时 editor 还活着）
      command({ id: newView.id, label: name, view: newView });
      // 3. 再 reload 更新目录树
      await ws.reload();
    } catch (e) {
      logger.error("create doc from mention failed", e);
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const handleCreateTable = async (name: string) => {
    try {
      const ws = useWorkspaceStore.getState();
      const wsId = ws.currentWorkspaceId;
      if (!wsId) return;
      // 1. 创建 grid 视图
      const newView = await viewApi.create({ workspace_id: wsId, parent_id: null, name, layout: "grid" });
      // 2. 预置默认字段（名称/日期/单选 + 两个选项 + 一行空行）
      await databaseApi.createField(newView.id, "text", t("field.exampleName"));
      await databaseApi.createField(newView.id, "date", t("field.exampleDate"));
      const select = await databaseApi.createField(newView.id, "single_select", t("field.exampleSelect"));
      await databaseApi.updateFieldOptions(select.id, {
        kind: "select",
        options: [
          newSelectOption(t("field.exampleOption", { n: 1 })),
          newSelectOption(t("field.exampleOption", { n: 2 })),
        ],
      });
      await databaseApi.createRow(newView.id);
      // 3. 先插入 mention 节点（此时 editor 还活着）
      command({ id: newView.id, label: name, view: newView });
      // 4. 再 reload 更新目录树
      await ws.reload();
    } catch (e) {
      logger.error("create table from mention failed", e);
      toast.error(t("error.db", { message: String(e) }));
    }
  };

  const handleSelect = (item: MentionItem) => {
    if (item.id === "__create_doc__") {
      void handleCreateDoc(item.label);
    } else if (item.id === "__create_table__") {
      void handleCreateTable(item.label);
    } else {
      command(item);
    }
  };

  return (
    <div className="w-[280px] rounded-lg border border-neutral-300 bg-white shadow-lg">
      {/* 搜索框 */}
      <div className="border-b border-neutral-200 px-2 py-1.5">
        <input
          autoFocus
          className="w-full bg-transparent text-[13px] text-neutral-700 outline-none placeholder:text-neutral-400"
          placeholder={t("mention.search")}
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Enter") {
              if (allOptions[active]) handleSelect(allOptions[active]);
            }
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              e.preventDefault();
              onKeyDown(new KeyboardEvent("keydown", { key: e.key }));
            }
          }}
        />
      </div>

      {/* 列表 */}
      {allOptions.length === 0 ? (
        <div className="px-3 py-2 text-[12.5px] text-neutral-400">{t("mention.empty")}</div>
      ) : (
        <div ref={listRef} className="max-h-[280px] overflow-y-auto py-1">
          {allOptions.map((it, i) => {
            const isCreateDoc = it.id === "__create_doc__";
            const isCreateTable = it.id === "__create_table__";
            return (
              <button
                key={it.id}
                data-active={i === active}
                className={
                  "flex w-full items-center gap-2 px-3 py-1.5 text-left text-[13px] " +
                  (i === active ? "bg-brand-100 text-neutral-800" : "text-neutral-600")
                }
                onMouseEnter={() => setActive(i)}
                onClick={() => handleSelect(it)}
              >
                <span className="flex w-5 shrink-0 items-center justify-center">
                  {isCreateDoc ? (
                    <FileText className="h-4 w-4 text-brand-500" />
                  ) : isCreateTable ? (
                    <Table2 className="h-4 w-4 text-brand-500" />
                  ) : (
                    <span className="text-base leading-none">{it.view ? viewIcon(it.view) : "📄"}</span>
                  )}
                </span>
                <span className="min-w-0 flex-1 truncate">
                  {isCreateDoc
                    ? t("mention.createDoc", { name: it.label })
                    : isCreateTable
                      ? t("mention.createTable", { name: it.label })
                      : it.label}
                </span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// —— @tiptap/extension-mention suggestion 配置 ——
export function buildMentionSuggestion(): MentionOptions["suggestion"] {
  return {
    items: ({ query }): MentionItem[] => {
      try {
        const state = useWorkspaceStore.getState();
        const list: View[] = flattenTree(state.tree);
        const filtered = list.filter((v) => {
          try {
            const extra = JSON.parse(v.extra) as { row_detail?: unknown };
            if (extra.row_detail) return false;
          } catch {
            // ignore
          }
          if (!query.trim()) return true;
          const q = query.toLowerCase();
          return v.name.toLowerCase().includes(q);
        });
        return filtered.slice(0, 10).map((v) => ({
          id: v.id,
          label: v.name || t("common.untitled"),
          view: v,
        }));
      } catch (e) {
        logger.error("mention.items failed", e);
        return [];
      }
    },
    render: () => {
      let component: ReactRenderer<MentionListHandle> | null = null;
      let unmount: (() => void) | null = null;
      return {
        onStart: (props) => {
          component = new ReactRenderer(MentionList, {
            props: {
              items: props.items,
              command: props.command,
              query: props.query,
            },
            editor: props.editor,
          });
          unmount = props.mount(component.element);
        },
        onUpdate: (props) => {
          component?.updateProps({
            items: props.items,
            command: props.command,
            query: props.query,
          });
        },
        onExit: () => {
          unmount?.();
          component?.destroy();
          component = null;
          unmount = null;
        },
        onKeyDown: ({ event }) => {
          if (event.key === "Escape") return true;
          return component?.ref?.onKeyDown(event) ?? false;
        },
      };
    },
  };
}

