/**
 * 弹层（调色板/链接输入）翻转判定：工具栏贴近编辑区底部时，默认向下展开（top-full）
 * 会超出可视区，此时改向上展开（bottom-full）。依据：弹层高度 > 下方剩余空间，
 * 且上方空间更大。
 */
function usePopoverFlip(editor: Editor | undefined, childRef: React.RefObject<HTMLDivElement | null>) {
  const [flip, setFlip] = useState(false);
  useLayoutEffect(() => {
    const el = childRef.current;
    if (!el) return;
    const parent = el.offsetParent as HTMLElement | null;
    if (!parent) return;
    const h = el.offsetHeight;
    const pr = parent.getBoundingClientRect();
    const rect = getEditorViewportRect(editor);
    const bottom = rect ? rect.bottom : window.innerHeight;
    const top = rect ? rect.top : 0;
    const spaceBelow = bottom - pr.bottom;
    const spaceAbove = pr.top - top;
    setFlip(spaceBelow < h && spaceAbove > spaceBelow);
    // childRef 是稳定 ref 引用，无需列入依赖
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editor]);
  return flip;
}

function SwatchPalette<T extends SwatchPal>(props: {
  title: string;
  palette: T;
  current: string | null;
  onPick: (value: string) => void;
  onClose: () => void;
  editor: Editor | undefined;
}) {
  const { palette, current, onPick, title, editor } = props;
  const ref = useRef<HTMLDivElement>(null);
  const flip = usePopoverFlip(editor, ref);
  useEffect(() => {
    const onClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) props.onClose();
    };
    window.addEventListener("mousedown", onClick);
    return () => window.removeEventListener("mousedown", onClick);
  }, [props]);
  return (
    <div
      ref={ref}
      className={cn(
        "absolute left-0 z-50 rounded-lg border border-neutral-300 bg-white p-2 shadow-lg",
        flip ? "bottom-full mb-1" : "top-full mt-1",
      )}
      onMouseDown={(e) => e.preventDefault()}
    >
      <div className="mb-1 px-1 text-[11px] text-neutral-400">{title}</div>
      <div className="flex gap-1.5">
        {palette.map((c) => (
          <button
            key={c.name + c.value}
            type="button"
            title={c.name}
            className={cn(
              "flex h-6 w-6 items-center justify-center rounded-full border border-neutral-200",
              c.swatch,
              current === c.value && "ring-2 ring-brand-500 ring-offset-1",
            )}
            onClick={() => onPick(c.value)}
          >
            {current === c.value && <Check className="h-3 w-3 text-white drop-shadow" />}
          </button>
        ))}
      </div>
    </div>
  );
}

function LinkPopover(props: {
  current: string | null;
  onSubmit: (url: string | null) => void;
  onClose: () => void;
  editor: Editor | undefined;
}) {
  const [value, setValue] = useState(props.current ?? "");
  const ref = useRef<HTMLDivElement>(null);
  const flip = usePopoverFlip(props.editor, ref);
  useEffect(() => {
    const onClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) props.onClose();
    };
    window.addEventListener("mousedown", onClick);
    return () => window.removeEventListener("mousedown", onClick);
  }, [props]);
  return (
    <div
      ref={ref}
      className={cn(
        "absolute left-0 z-50 flex items-center gap-1 rounded-lg border border-neutral-300 bg-white p-1 shadow-lg",
        flip ? "bottom-full mb-1" : "top-full mt-1",
      )}
      onMouseDown={(e) => e.preventDefault()}
    >
      <input
        autoFocus
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder={t("float.linkPlaceholder")}
        className="h-7 w-56 rounded border-none bg-transparent px-2 text-[13px] outline-none placeholder:text-neutral-400"
        onKeyDown={(e) => {
          if (e.key === "Enter") props.onSubmit(value.trim() || null);
          if (e.key === "Escape") props.onClose();
        }}
      />
      {/* 语义：已有链接时 = 取消链接；无链接时 = 关闭（取消输入） */}
      <IconBtn
        title={props.current ? t("float.unlink") : t("common.cancel")}
        onClick={() => {
          if (props.current) props.onSubmit(null);
          else props.onClose();
        }}
      >
        {props.current ? <Unlink className="h-3.5 w-3.5" /> : <Eraser className="h-3.5 w-3.5" />}
      </IconBtn>
      <IconBtn title={t("common.confirm")} onClick={() => props.onSubmit(value.trim() || null)}>
        <Check className="h-3.5 w-3.5" />
      </IconBtn>
    </div>
  );
}

export function FloatingMenu(props: { editor: Editor | undefined }) {
  const { editor } = props;
  const boxRef = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);
  const [coord, setCoord] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [placed, setPlaced] = useState<{ x: number; y: number } | null>(null);
  const [colorOpen, setColorOpen] = useState(false);
  const [highlightOpen, setHighlightOpen] = useState(false);
  const [linkOpen, setLinkOpen] = useState(false);
  const [, forceUpdate] = useState(0); // editor state 变化时刷新 active 态

  useEffect(() => {
    if (!editor) return;
    /** 判断是否是真正的"字符范围选择"（TextSelection 且 from!==to），排除 NodeSelection/AllSelection
     *  —— 防止打开页面/加载文档时因 ProseMirror 内部 NodeSelection 初始化事件触发工具栏默认显示（需求2彻底修复）
     */
    const isCharSelection = (sel: Selection): boolean => {
      if (sel.empty) return false;
      const name: string | undefined = sel.constructor.name;
      if (name) {
        if (name !== "TextSelection") return false; // NodeSelection/AllSelection/GapSelection etc 一律不显示
      } else {
        // Fallback：没有 constructor name 就通过"起点/终点都在 inline 文本块中"判断
        try {
          const { $from, $to } = sel;
          if (!$from.parent.isTextblock || !$to.parent.isTextblock) return false;
        } catch {
          return false;
        }
      }
      if (typeof sel.from !== "number" || typeof sel.to !== "number") return false;
      if (sel.from >= sel.to) return false;
      return true;
    };

    const update = () => {
      forceUpdate((x) => x + 1);
      const sel = editor.state.selection;
      // 需求2（严格门）：必须是字符范围选择
      if (!isCharSelection(sel)) {
        setVisible(false);
        return;
      }
      // 跳过图片/代码块/表格/数据库/其他 atom 容器节点
      const forbidden = [
        "image",
        "codeBlock",
        "table",
        "math",
        "databaseView",
        "attachment",
        "callout",
        "toggle",
        "columns",
        "imageGallery",
        "outline",
      ];
      for (const name of forbidden) {
        if (editor.isActive(name)) {
          setVisible(false);
          return;
        }
      }
      // ProseMirror view 给出选区边界屏幕坐标
      try {
        const from = editor.view.coordsAtPos(sel.from);
        const to = editor.view.coordsAtPos(sel.to);
        const x = (from.left + to.right) / 2;
        const y = from.top - 8; // 顶部上方 8px
        setCoord({ x, y });
        setVisible(true);
      } catch {
        setVisible(false);
      }
    };
    editor.on("selectionUpdate", update);
    editor.on("update", update);
    editor.on("blur", () => {
      // 延迟：点击自己工具栏前 blur 会触发；用 rAF 让 onMouseDown 的 preventDefault 阻止 blur 之后再隐藏
      requestAnimationFrame(() => {
        if (!document.activeElement || boxRef.current?.contains(document.activeElement)) return;
        if (boxRef.current?.matches(":hover")) return;
        setVisible(false);
      });
    });
    update();
    return () => {
      editor.off("selectionUpdate", update);
      editor.off("update", update);
    };
  }, [editor]);

  // 滚动时关闭（避免坐标错位）
  useEffect(() => {
    if (!visible) return;
    const onScroll = () => setVisible(false);
    window.addEventListener("scroll", onScroll, true);
    return () => window.removeEventListener("scroll", onScroll, true);
  }, [visible]);

  // 渲染后量测实际尺寸，把 fixed 浮层 clamp 进编辑区可视矩形（窄面板不飘出编辑区）
  useLayoutEffect(() => {
    if (!visible || !boxRef.current || !editor) return;
    const w = boxRef.current.offsetWidth;
    const h = boxRef.current.offsetHeight;
    if (!w || !h) return;
    // 原定位：translate(-50%,-100%)，即盒子左下角落在 (coord.x, coord.y)
    const rawLeft = coord.x - w / 2;
    const rawTop = coord.y - h;
    setPlaced(clampFloatToEditor(editor, rawLeft, rawTop, w, h));
  }, [visible, coord, editor]);

  // 需求2：渲染级再兜一层 —— 只有 TextSelection（字符范围）选中才渲染
  const selection = editor?.state.selection;
  const isCharSelection =
    !!selection &&
    !selection.empty &&
    typeof selection.from === "number" &&
    typeof selection.to === "number" &&
    selection.from < selection.to &&
    selection.constructor.name === "TextSelection";
  if (!editor || !visible || !isCharSelection) return null;

  const closeAll = () => {
    setColorOpen(false);
    setHighlightOpen(false);
    setLinkOpen(false);
  };

  const currentTextColor = (() => {
    const s = editor.getAttributes("textStyle");
    return typeof s.color === "string" ? s.color : null;
  })();
  const currentHighlight = (() => {
    const s = editor.getAttributes("highlight");
    return typeof s.color === "string" ? s.color : "transparent";
  })();
  const currentLink = (() => {
    const s = editor.getAttributes("link");
    return typeof s.href === "string" ? s.href : null;
  })();

  // Box 尺寸由内容决定；定位：fixed 居中（render 后 layout 量测 → clamp 到编辑区内）
  return (
    <div
      ref={boxRef}
      style={{
        position: "fixed",
        left: `${placed?.x ?? coord.x}px`,
        top: `${placed?.y ?? coord.y - 40}px`,
        zIndex: 50,
      }}
      onMouseDown={(e) => e.preventDefault()}
      onMouseLeave={() => {
        /* noop */
      }}
    >
      <div className="relative flex items-center rounded-lg border border-neutral-200 bg-white px-1 py-1 shadow-lg">
        <IconBtn
          title={t("float.bold")}
          active={editor.isActive("bold")}
          onClick={() => editor.chain().focus().toggleBold().run()}
        >
          <Bold className="h-4 w-4" />
        </IconBtn>
        <IconBtn
          title={t("float.italic")}
          active={editor.isActive("italic")}
          onClick={() => editor.chain().focus().toggleItalic().run()}
        >
          <Italic className="h-4 w-4" />
        </IconBtn>
        <IconBtn
          title={t("float.underline")}
          active={editor.isActive("underline")}
          onClick={() => editor.chain().focus().toggleUnderline().run()}
        >
          <Underline className="h-4 w-4" />
        </IconBtn>
        <IconBtn
          title={t("float.strike")}
          active={editor.isActive("strike")}
          onClick={() => editor.chain().focus().toggleStrike().run()}
        >
          <Strikethrough className="h-4 w-4" />
        </IconBtn>
        <Divider />
        <div className="relative">
          <IconBtn
            title={t("float.highlight")}
            active={currentHighlight !== "transparent"}
            onClick={() => {
              setHighlightOpen((v) => !v);
              setColorOpen(false);
              setLinkOpen(false);
            }}
          >
            <Highlighter className="h-4 w-4" />
          </IconBtn>
          {highlightOpen && (
            <SwatchPalette
              title={t("float.highlight")}
              palette={HIGHLIGHT_COLORS}
              current={currentHighlight}
              editor={editor}
              onPick={(v) => {
                if (v === "transparent") editor.chain().focus().unsetHighlight().run();
                else editor.chain().focus().setHighlight({ color: v }).run();
                setHighlightOpen(false);
              }}
              onClose={() => setHighlightOpen(false)}
            />
          )}
        </div>
        <div className="relative">
          <IconBtn
            title={t("float.color")}
            active={!!currentTextColor}
            onClick={() => {
              setColorOpen((v) => !v);
              setHighlightOpen(false);
              setLinkOpen(false);
            }}
          >
            <Palette className="h-4 w-4" />
          </IconBtn>
          {colorOpen && (
            <SwatchPalette
              title={t("float.color")}
              palette={TEXT_COLORS}
              current={currentTextColor}
              editor={editor}
              onPick={(v) => {
                if (v === "inherit") editor.chain().focus().unsetColor().run();
                else editor.chain().focus().setColor(v).run();
                setColorOpen(false);
              }}
              onClose={() => setColorOpen(false)}
            />
          )}
        </div>
        <div className="relative">
          <IconBtn
            title={t("float.link")}
            active={!!currentLink}
            onClick={() => {
              closeAll();
              setLinkOpen(!linkOpen);
            }}
          >
            <Link2 className="h-4 w-4" />
          </IconBtn>
          {linkOpen && (
            <LinkPopover
              current={currentLink}
              editor={editor}
              onSubmit={(url) => {
                if (!url) editor.chain().focus().unsetLink().run();
                else editor.chain().focus().setLink({ href: url, target: "_blank", rel: "noopener noreferrer" }).run();
                setLinkOpen(false);
              }}
              onClose={() => setLinkOpen(false)}
            />
          )}
        </div>
        {!!currentLink && (
          <IconBtn title={t("float.unlink")} onClick={() => editor.chain().focus().unsetLink().run()}>
            <Unlink className="h-4 w-4" />
          </IconBtn>
        )}
        <Divider />
        <IconBtn
          title={t("float.code")}
          active={editor.isActive("code")}
          onClick={() => editor.chain().focus().toggleCode().run()}
        >
          <Code className="h-4 w-4" />
        </IconBtn>
        <Divider />
        <IconBtn
          title={t("float.clearFormat")}
          onClick={() => editor.chain().focus().clearNodes().unsetAllMarks().run()}
        >
          <Eraser className="h-4 w-4" />
        </IconBtn>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Star, X } from "lucide-react";
import { parseViewTags } from "@/types/models";
import { PageTreeItem, type DropHint } from "./PageTreeItem";
import { useWorkspaceStore } from "@/stores/workspace";
import {
  dropTarget,
  filterTreeByTag,
  flattenTree,
  flattenVisibleTree,
  isDescendant,
  type DropZone,
  type VisibleTreeRow,
} from "@/lib/tree";
import { t } from "@/lib/i18n";
import { tagColor, tagTint } from "@/lib/tags";
import { logger } from "@/lib/logger";
import { toast } from "sonner";

/** 行高（PageTreeItem 的行容器固定 h-[30px]）：窗口化按固定行高换算，无需测量 */
const ROW_H = 30;
/** 窗口化阈值：可见行数超过它才启用（小树保持全量渲染，零行为差异） */
const VIRTUAL_MIN_ROWS = 150;
/** 视口上下各多渲染的行数：抵消快速滚动时的白屏 */
const VIRTUAL_OVERSCAN = 12;

/** 页面树：展平成同级行渲染（跟随展开状态）+ 大列表窗口化。
 *  鼠标事件链拖拽（HTML5 drag 在 WebView2 下不可靠，与编辑器块拖拽同方案），行仍带 data-tree-row。
 *  顶部含收藏区（跨目录快速入口）与标签过滤行（点击按标签过滤树）。 */
export function PageTree() {
  const tree = useWorkspaceStore((s) => s.tree);
  const expanded = useWorkspaceStore((s) => s.expanded);
  const moveView = useWorkspaceStore((s) => s.moveView);
  const openView = useWorkspaceStore((s) => s.openView);
  const expand = useWorkspaceStore((s) => s.expand);
  const tagFilter = useWorkspaceStore((s) => s.tagFilter);
  const setTagFilter = useWorkspaceStore((s) => s.setTagFilter);
  const tagMeta = useWorkspaceStore((s) => s.tagMeta);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dropHint, setDropHint] = useState<DropHint | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  /** 拖拽会话（mousedown 记录 → mousemove 超阈值进入拖拽 → mouseup 落点） */
  const sessionRef = useRef<{ id: string; startX: number; startY: number; moved: boolean } | null>(null);
  /** 拖拽落点后的同帧 click 抑制 */
  const suppressClickRef = useRef(false);

  const favorites = useMemo(() => flattenTree(tree).filter((v) => v.is_favorite === 1), [tree]);
  const allTags = useMemo(() => {
    const set = new Set<string>();
    for (const v of flattenTree(tree)) for (const tag of parseViewTags(v.tags)) set.add(tag);
    return [...set].sort((a, b) => a.localeCompare(b));
  }, [tree]);

  const displayTree = useMemo(() => (tagFilter ? filterTreeByTag(tree, tagFilter) : tree), [tree, tagFilter]);

  /** 展平成同级行：跟随展开状态决定是否下钻（替代原先的递归渲染） */
  const rows = useMemo(() => flattenVisibleTree(displayTree, expanded), [displayTree, expanded]);

  // ---------- 大列表窗口化 ----------
  // 行高固定 30px，行数超阈值时只渲染视口附近的行，用占位高度撑住滚动条；
  // 阈值以下走原路径，小树零行为变化。
  const listRef = useRef<HTMLDivElement | null>(null);
  const [win, setWin] = useState<{ start: number; end: number } | null>(null);
  const virtual = rows.length > VIRTUAL_MIN_ROWS;

  // 收藏区/标签行在树之前，先量出"列表在滚动内容里的 y 偏移"再折算窗口，否则越滚越偏
  const measureWindow = useCallback(() => {
    const el = containerRef.current;
    const list = listRef.current;
    if (!el || !list) return;
    const listTop = list.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop;
    const total = rows.length;
    const start = Math.max(0, Math.floor((el.scrollTop - listTop) / ROW_H) - VIRTUAL_OVERSCAN);
    const end = Math.min(total, Math.ceil((el.scrollTop - listTop + el.clientHeight) / ROW_H) + VIRTUAL_OVERSCAN);
    const next = { start, end: Math.max(end, Math.min(total, start + 1)) };
    setWin((prev) => (prev?.start === next.start && prev.end === next.end ? prev : next));
  }, [rows.length]);

  useEffect(() => {
    if (!virtual) {
      setWin(null);
      return;
    }
    const el = containerRef.current;
    if (!el) return;
    measureWindow();
    const onScroll = () => measureWindow();
    el.addEventListener("scroll", onScroll, { passive: true });
    const ro = new ResizeObserver(() => measureWindow());
    ro.observe(el);
    return () => {
      el.removeEventListener("scroll", onScroll);
      ro.disconnect();
    };
  }, [virtual, measureWindow]);

  const onMoveFail = (e: unknown) => {
    logger.error("move view failed", e);
    toast.error(t("error.db", { message: String(e) }));
  };

  const handleDrop = async (viewId: string, targetId: string, zone: DropZone) => {
    const target = dropTarget(tree, targetId, zone);
    if (!target) return;
    try {
      await moveView(viewId, target.parentId, target.index);
    } catch (e: unknown) {
      onMoveFail(e);
    }
  };

  useEffect(() => {
    const zoneForEl = (row: HTMLElement, clientY: number): DropZone => {
      const rect = row.getBoundingClientRect();
      const ratio = (clientY - rect.top) / rect.height;
      return ratio < 0.3 ? "before" : ratio > 0.7 ? "after" : "inside";
    };
    const rowAt = (el: EventTarget | null): HTMLElement | null => {
      if (!(el instanceof HTMLElement)) return null;
      return el.closest("[data-tree-row]");
    };

    const onMouseMove = (e: MouseEvent) => {
      const s = sessionRef.current;
      if (!s) return;
      if (!s.moved) {
        // 5px 阈值内视为点击（不进入拖拽）
        if (Math.abs(e.clientX - s.startX) + Math.abs(e.clientY - s.startY) < 5) return;
        s.moved = true;
        setDraggingId(s.id);
      }
      const row = rowAt(e.target);
      if (!row?.dataset.treeRow) {
        setDropHint(null);
        return;
      }
      const targetId = row.dataset.treeRow;
      const cur = useWorkspaceStore.getState().tree;
      // 拒绝条件：目标是被拖项自身或其后代（防环）；注意参数顺序——
      // isDescendant(tree, ancestor, x) 判 "x 在 ancestor 子树内"，父级行不是自己的后代，必须放行
      if (targetId === s.id || isDescendant(cur, s.id, targetId)) {
        setDropHint(null);
        return;
      }
      const zone = zoneForEl(row, e.clientY);
      setDropHint((prev) => (prev?.targetId === targetId && prev.zone === zone ? prev : { targetId, zone }));
    };

    const onMouseUp = (e: MouseEvent) => {
      const s = sessionRef.current;
      sessionRef.current = null;
      if (!s) return;
      if (!s.moved) return; // 未拖动：交给行 onClick 打开页面
      suppressClickRef.current = true;
      setTimeout(() => (suppressClickRef.current = false));
      const row = rowAt(e.target);
      const cur = useWorkspaceStore.getState().tree;
      if (row?.dataset.treeRow) {
        const targetId = row.dataset.treeRow;
        if (targetId !== s.id && !isDescendant(cur, s.id, targetId)) {
          const zone = zoneForEl(row, e.clientY);
          if (zone === "inside") expand(targetId);
          void handleDrop(s.id, targetId, zone);
        }
      } else if (containerRef.current?.contains(e.target as Node)) {
        // 树容器空白处落点 → 移到根级末尾
        void moveView(s.id, null, cur.length).catch(onMoveFail);
      }
      setDraggingId(null);
      setDropHint(null);
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
    return () => {
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tree, expand]);

  /** 行点击（会话未变成拖拽时打开页面） */
  const onRowClick = (id: string) => {
    if (suppressClickRef.current) return;
    openView(id);
  };

  /** 行 mousedown：左键且不在交互控件上时启动潜在拖拽会话 */
  const onRowMouseDown = (id: string, e: React.MouseEvent) => {
    if (e.button !== 0) return;
    if ((e.target as HTMLElement).closest("button, input, a, [role=button]")) return;
    e.preventDefault(); // 防止拖拽选中文本
    sessionRef.current = { id, startX: e.clientX, startY: e.clientY, moved: false };
  };

  // 首次 commit 还没量过窗口：先渲染开头一段，effect 量完立刻纠正
  const winStart = win?.start ?? 0;
  const winEnd = win?.end ?? Math.min(rows.length, VIRTUAL_OVERSCAN * 4);
  const renderRow = (r: VisibleTreeRow) => (
    <PageTreeItem
      key={r.node.id}
      node={r.node}
      depth={r.depth}
      draggingId={draggingId}
      dropHint={dropHint}
      onRowMouseDown={onRowMouseDown}
      onRowClick={onRowClick}
    />
  );

  return (
    <div
      ref={containerRef}
      className="flex-1 overflow-y-auto px-2 pb-2 [&::-webkit-scrollbar]:hidden [scrollbar-width:none]"
    >
      {/* 收藏区：有收藏页面时显示，点击直达（保留在树中原位置） */}
      {favorites.length > 0 && (
        <div className="mb-2 border-b border-neutral-200 pb-2">
          <div className="px-1 pb-1 text-[10px] font-medium uppercase tracking-wide text-neutral-400">
            {t("tree.favorites")}
          </div>
          {favorites.map((v) => (
            <button
              key={v.id}
              className="flex h-[28px] w-full items-center gap-1.5 rounded px-1 text-left hover:bg-neutral-300/40"
              onClick={() => openView(v.id)}
            >
              <Star className="h-3 w-3 shrink-0 fill-brand-500 text-brand-500" />
              <span className="min-w-0 flex-1 truncate text-[13px] text-neutral-700">{v.name}</span>
            </button>
          ))}
        </div>
      )}

      {/* 标签过滤行：点击标签过滤树，再次点击取消 */}
      {allTags.length > 0 && (
        <div className="mb-2 flex flex-wrap items-center gap-1.5">
          {allTags.map((tag) => {
            const on = tagFilter === tag;
            const color = tagColor(tag, tagMeta);
            return (
              <button
                key={tag}
                className={
                  "flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] transition " +
                  (on ? "" : "text-neutral-500 hover:text-neutral-700")
                }
                style={{
                  borderColor: on ? color : tagTint(color, "66"),
                  backgroundColor: on ? tagTint(color, "1f") : undefined,
                  color: on ? color : undefined,
                }}
                onClick={() => setTagFilter(on ? null : tag)}
              >
                <span className="h-1.5 w-1.5 shrink-0 rounded-full" style={{ backgroundColor: color }} />
                {tag}
                {on && <X className="h-3 w-3" />}
              </button>
            );
          })}
        </div>
      )}

      {rows.length === 0 && (
        <div className="px-2 py-3 text-center text-xs text-neutral-500">
          {tagFilter ? t("tree.noTagMatch") : t("tree.empty")}
        </div>
      )}
      {virtual ? (
        // 窗口化：外层撑出总高，行按固定行高绝对定位（首次 commit 未量过窗口时先渲染开头一段）
        <div ref={listRef} className="relative" style={{ height: rows.length * ROW_H }}>
          {rows.slice(winStart, winEnd).map((r, i) => (
            <div
              key={r.node.id}
              className="absolute left-0 right-0"
              style={{ top: (winStart + i) * ROW_H, height: ROW_H }}
            >
              {renderRow(r)}
            </div>
          ))}
        </div>
      ) : (
        rows.map(renderRow)
      )}
      {draggingId && !dropHint && <div className="mx-1 my-1 h-[2px] rounded bg-brand-500" />}
    </div>
  );
}
